  ('c492481f-6020-5432-9534-5bb605353de9', 'uk', 'Познайомитися з новим сусідом', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'be', 'Пазнаёміцца з новым суседам', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'pl', 'Poznaj nowego sąsiada', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'tr', 'Yeni komşunla tanış', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'zh', '认识新邻居', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'zh-Hant', '認識新鄰居', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'ja', '新しいご近所さんと知り合おう', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'ar', 'تعرّف على جارك الجديد', null),
  ('c492481f-6020-5432-9534-5bb605353de9', 'hi', 'अपने नए पड़ोसी से मिलें', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'en', 'Hello! Are you our new neighbour?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'es', '¡Hola! ¿Es usted nuestro nuevo vecino?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'fr', 'Bonjour ! Vous êtes notre nouveau voisin ?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'de', 'Hallo! Sind Sie unser neuer Nachbar?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'it', 'Buongiorno! È lei il nostro nuovo vicino?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'pt', 'Olá! É o nosso novo vizinho?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'ru', 'Здравствуйте! Вы наш новый сосед?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'uk', 'Добрий день! Ви наш новий сусід?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'be', 'Добры дзень! Вы наш новы сусед?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'pl', 'Dzień dobry! Pan jest nowym sąsiadem?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'tr', 'Merhaba! Yeni komşumuz siz misiniz?', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'zh', '你好！你是我们的新邻居吗？', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'zh-Hant', '你好！你是我們的新鄰居嗎？', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'ja', 'こんにちは！新しく引っ越してきた方ですか？', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'ar', 'مرحبًا! هل أنت جارنا الجديد؟', null),
  ('88b15a76-4719-526e-b7ae-358ea3ed5f35', 'hi', 'नमस्ते! क्या आप हमारे नए पड़ोसी हैं?', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'en', 'Hello! Yes, I''m new.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'es', '¡Hola! Sí, soy nuevo.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'fr', 'Bonjour ! Oui, je viens d''arriver.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'de', 'Hallo! Ja, ich bin neu hier.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'it', 'Buongiorno! Sì, sono nuovo.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'pt', 'Olá! Sim, sou novo aqui.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'ru', 'Здравствуйте! Да, я новенький.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'uk', 'Добрий день! Так, я новенький.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'be', 'Добры дзень! Так, я тут новы.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'pl', 'Dzień dobry! Tak, jestem nowy.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'tr', 'Merhaba! Evet, yeni taşındım.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'zh', '你好！对，我刚搬来。', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'zh-Hant', '你好！對，我剛搬來。', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'ja', 'こんにちは！はい、引っ越してきたばかりです。', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'ar', 'مرحبًا! نعم، أنا جديد هنا.', null),
  ('a4e69895-db25-541e-8bc9-02f6c9d418b2', 'hi', 'नमस्ते! हाँ, मैं नया हूँ।', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'en', 'I''m Thomas, but call me Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'es', 'Soy Thomas, pero llámame Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'fr', 'Je suis Thomas, mais appelle-moi Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'de', 'Ich bin Thomas, aber nenn mich einfach Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'it', 'Sono Thomas, ma chiamami Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'pt', 'Sou o Thomas, mas trata-me por Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'ru', 'Я Томас, но зови меня просто Том.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'uk', 'Я Томас, але клич мене просто Том.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'be', 'Я Томас, але кліч мяне проста Том.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'pl', 'Jestem Thomas, ale mów mi Tom.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'tr', 'Ben Thomas, ama bana Tom de.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'zh', '我叫托马斯，不过叫我汤姆就行。', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'zh-Hant', '我叫湯瑪斯，不過叫我湯姆就好。', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'ja', 'トーマスです。でも、トムって呼んで。', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'ar', 'أنا توماس، لكن نادِني توم.', null),
  ('4b0a42f7-dee5-555b-adfa-e0d0a578af03', 'hi', 'मैं थॉमस हूँ, पर मुझे टॉम बुलाओ।', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'en', 'Sure! Nice to meet you, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'es', '¡Claro! Encantado, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'fr', 'Bien sûr ! Enchanté, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'de', 'Klar! Freut mich, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'it', 'Certo! Piacere, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'pt', 'Claro! Muito prazer, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'ru', 'Конечно! Приятно познакомиться, Том.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'uk', 'Звісно! Приємно познайомитися, Томе.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'be', 'Вядома! Прыемна пазнаёміцца, Том.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'pl', 'Jasne! Miło mi, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'tr', 'Tabii! Memnun oldum, Tom.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'zh', '好的！很高兴认识你，汤姆。', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'zh-Hant', '好啊！很高興認識你，湯姆。', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'ja', 'もちろん！よろしくね、トム。', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'ar', 'بالتأكيد! تشرفت بمعرفتك يا توم.', null),
  ('bceca75e-3c73-58cb-9556-8cfa7d943857', 'hi', 'ज़रूर! तुमसे मिलकर अच्छा लगा, टॉम।', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'en', 'You too! If you need anything, I live next door.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'es', '¡Igualmente! Si necesitas algo, vivo al lado.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'fr', 'Moi aussi ! Si tu as besoin de quelque chose, j''habite à côté.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'de', 'Mich auch! Wenn du etwas brauchst: Ich wohne nebenan.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'it', 'Piacere mio! Se ti serve qualcosa, abito qui accanto.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'pt', 'Igualmente! Se precisares de alguma coisa, moro aqui ao lado.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'ru', 'Мне тоже! Если что, я живу по соседству.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'uk', 'Мені теж! Якщо що, я живу по сусідству.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'be', 'Мне таксама! Калі што, я жыву па суседстве.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'pl', 'Mnie też! Jakby co, mieszkam obok.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'tr', 'Ben de! Bir şeye ihtiyacın olursa, hemen yanda oturuyorum.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'zh', '我也是！有什么需要的话，我就住隔壁。', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'zh-Hant', '我也是！有需要什麼的話，我就住隔壁。', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'ja', 'こちらこそ！何かあったら言ってね、隣に住んでるから。', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'ar', 'وأنا أيضًا! إذا احتجت أي شيء، فأنا أسكن في البيت المجاور.', null),
  ('e31def7b-3f5d-573a-9f5f-8db813ff5c27', 'hi', 'मुझे भी! कुछ भी चाहिए हो, तो मैं बगल में ही रहता हूँ।', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'en', 'Thanks, Tom! See you!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'es', '¡Gracias, Tom! ¡Hasta luego!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'fr', 'Merci, Tom ! À plus !', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'de', 'Danke, Tom! Bis dann!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'it', 'Grazie, Tom! Ci vediamo!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'pt', 'Obrigado, Tom! Até logo!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'ru', 'Спасибо, Том! Пока!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'uk', 'Дякую, Томе! Бувай!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'be', 'Дзякуй, Том! Пакуль!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'pl', 'Dzięki, Tom! Na razie!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'tr', 'Sağ ol, Tom! Görüşürüz!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'zh', '谢谢你，汤姆！回头见！', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'zh-Hant', '謝謝你，湯姆！再見！', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'ja', 'ありがとう、トム！またね！', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'ar', 'شكرًا يا توم! إلى اللقاء!', null),
  ('1bfb519d-33be-534d-99da-0c6f86a343a0', 'hi', 'शुक्रिया, टॉम! फिर मिलेंगे!', null),
