  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'en', 'Hello! How can I help you?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'es', '¡Hola! ¿En qué puedo ayudarle?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'fr', 'Bonjour ! Je peux vous aider ?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'de', 'Hallo! Kann ich Ihnen helfen?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'it', 'Buongiorno! Come posso aiutarla?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'pt', 'Olá! Em que posso ajudar?', null),
