  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'uk', 'Добрий день! Чим можу допомогти?', null),
  ('65bc52ec-1737-5985-b0af-9e6d9ec821e7', 'be', 'Добры дзень! Чым магу дапамагчы?', null),
