  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'en', 'Could you say that again more slowly?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'es', '¿Puede repetirlo más despacio?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'fr', 'Vous pouvez répéter plus lentement ?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'de', 'Können Sie das bitte langsamer wiederholen?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'it', 'Può ripetere più lentamente?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'pt', 'Pode repetir mais devagar, por favor?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'ru', 'Можете повторить помедленнее?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'uk', 'Можете повторити повільніше?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'be', 'Можаце паўтарыць павольней?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'pl', 'Może pani powtórzyć wolniej?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'tr', 'Daha yavaş tekrar edebilir misiniz?', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'zh', '您能说慢一点，再说一遍吗？', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'zh-Hant', '可以請您說慢一點，再說一次嗎？', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'ja', 'もう一度、もう少しゆっくり言っていただけますか？', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'ar', 'هل يمكنك أن تعيد ذلك ببطء أكثر؟', null),
  ('18b16c00-fa03-5513-a176-b753eabd0f1d', 'hi', 'क्या आप इसे थोड़ा धीरे दोबारा कह सकते हैं?', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'en', 'Of course. Write your name here, and sign here.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'es', 'Por supuesto. Escriba aquí su nombre y firme aquí.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'fr', 'Bien sûr. Écrivez votre nom ici, et signez là.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'de', 'Natürlich. Schreiben Sie hier Ihren Namen hin und unterschreiben Sie hier.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'it', 'Certo. Scriva qui il suo nome e firmi qui.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'pt', 'Claro. Escreva aqui o seu nome e assine aqui.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'ru', 'Конечно. Напишите здесь своё имя и распишитесь вот здесь.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'uk', 'Звісно. Напишіть тут своє ім''я і розпишіться ось тут.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'be', 'Вядома. Напішыце тут сваё імя і распішыцеся вось тут.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'pl', 'Oczywiście. Proszę wpisać tutaj imię i podpisać tutaj.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'tr', 'Tabii. Adınızı buraya yazın, buraya da imzanızı atın.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'zh', '当然。在这里写上您的名字，在这里签字。', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'zh-Hant', '當然。請在這裡寫上您的名字，然後在這裡簽名。', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'ja', 'もちろんです。ここにお名前を書いて、ここにサインしてください。', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'ar', 'طبعًا. اكتب اسمك هنا، ووقّع هنا.', null),
  ('4d9cef50-4e8e-5d14-818c-ac03d35b0471', 'hi', 'ज़रूर। यहाँ अपना नाम लिखिए, और यहाँ हस्ताक्षर कीजिए।', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'en', 'Oh, now I understand! Thank you.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'es', '¡Ah, ahora lo entiendo! Gracias.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'fr', 'Ah, maintenant je comprends ! Merci.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'de', 'Ah, jetzt verstehe ich! Danke.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'it', 'Ah, ora capisco! Grazie.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'pt', 'Ah, agora percebo! Obrigado.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'ru', 'А, теперь понимаю! Спасибо.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'uk', 'А, тепер розумію! Дякую.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'be', 'А, цяпер разумею! Дзякуй.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'pl', 'Aha, teraz rozumiem! Dziękuję.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'tr', 'Ha, şimdi anladım! Teşekkürler.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'zh', '哦，现在我明白了！谢谢。', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'zh-Hant', '喔，我現在懂了！謝謝。', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'ja', 'ああ、やっとわかりました！ありがとうございます。', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'ar', 'آه، الآن فهمت! شكرًا.', null),
  ('4792ce1f-d204-5310-9bb8-dc7ede63c292', 'hi', 'अच्छा, अब समझ आया! धन्यवाद।', null),
