  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'en', 'My name is Alex. And you?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'es', 'Me llamo Alex. ¿Y tú?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'fr', 'Je m''appelle Alex. Et toi ?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'de', 'Ich heiße Alex. Und du?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'it', 'Mi chiamo Alex. E tu?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'pt', 'Chamo-me Alex. E tu?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'ru', 'Меня зовут Алекс. А тебя?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'uk', 'Мене звати Алекс. А тебе?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'be', 'Мяне завуць Алекс. А цябе?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'pl', 'Mam na imię Alex. A ty?', null),
  ('f425a45d-70b0-53c1-8f8a-d228e3c1bb15', 'tr', 'Benim adım Alex. Ya seninki?', null),
