  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'en', 'I''m Tom. Nice to meet you! Where are you from?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'es', 'Soy Tom. ¡Encantado! ¿De dónde eres?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'fr', 'Moi, c''est Tom. Enchanté ! Tu viens d''où ?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'de', 'Ich bin Tom. Freut mich! Woher kommst du?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'it', 'Sono Tom. Piacere! Di dove sei?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'pt', 'Sou o Tom. Muito prazer! De onde és?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'ru', 'Я Том. Приятно познакомиться! Откуда ты?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'uk', 'Я Том. Приємно познайомитися! Звідки ти?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'be', 'Я Том. Прыемна пазнаёміцца! Адкуль ты?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'pl', 'Jestem Tom. Miło mi! Skąd jesteś?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'tr', 'Ben Tom. Memnun oldum! Nerelisin?', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'zh', '我是汤姆。很高兴认识你！你是哪里人？', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'zh-Hant', '我是湯姆。很高興認識你！你是哪裡人？', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'ja', 'トムだよ。はじめまして！どこから来たの？', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'ar', 'أنا توم. تشرفت بمعرفتك! من أين أنت؟', null),
  ('7a87a56d-cf11-5758-b266-09ca200901b9', 'hi', 'मैं टॉम हूँ। तुमसे मिलकर अच्छा लगा! तुम कहाँ से हो?', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'en', 'Nice to meet you too! I''m from the forest.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'es', '¡Igualmente! Soy del bosque.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'fr', 'Enchanté aussi ! Je viens de la forêt.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'de', 'Freut mich auch! Ich komme aus dem Wald.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'it', 'Piacere mio! Vengo dal bosco.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'pt', 'O prazer é meu! Sou da floresta.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'ru', 'Мне тоже приятно! Я из леса.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'uk', 'Мені теж приємно! Я з лісу.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'be', 'Мне таксама прыемна! Я з лесу.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'pl', 'Mnie też miło! Jestem z lasu.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'tr', 'Ben de memnun oldum! Ormandan geliyorum.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'zh', '我也很高兴认识你！我来自森林。', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'zh-Hant', '我也很高興認識你！我來自森林。', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'ja', 'こちらこそ、はじめまして！森から来たんだ。', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'ar', 'وأنا أيضًا! أنا من الغابة.', null),
  ('a5e4b22f-a477-52af-8021-f9b2b79bdd58', 'hi', 'मुझे भी तुमसे मिलकर अच्छा लगा! मैं जंगल से हूँ।', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'en', 'Great! And where do you live now?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'es', '¡Genial! ¿Y dónde vives ahora?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'fr', 'Génial ! Et tu habites où maintenant ?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'de', 'Toll! Und wo wohnst du jetzt?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'it', 'Fantastico! E dove abiti adesso?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'pt', 'Boa! E onde vives agora?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'ru', 'Здорово! А где ты сейчас живёшь?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'uk', 'Чудово! А де ти зараз живеш?', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'be', 'Цудоўна! А дзе ты цяпер жывеш?', null),
