  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'zh', '太好了！那你现在住在哪儿？', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'zh-Hant', '太好了！那你現在住在哪裡？', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'ja', 'いいね！で、今はどこに住んでるの？', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'ar', 'رائع! وأين تسكن الآن؟', null),
  ('514334f7-5d45-5a42-a221-1567fb17ab50', 'hi', 'बढ़िया! और अब तुम कहाँ रहते हो?', null),
