  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'pt', 'Está bem. E depois?', null),
  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'ru', 'Хорошо. А дальше?', null),
  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'uk', 'Добре. А далі?', null),
