  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'tr', 'Tamam. Sonra?', null),
  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'zh', '好的。然后呢？', null),
  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'zh-Hant', '好。然後呢？', null),
  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'ja', 'はい。その次は？', null),
