  ('ef80be86-e9ee-5075-bf42-28343ff31b37', 'hi', 'ठीक है। और उसके बाद?', null),
  ('5e1f2b33-2244-58e6-9dd4-c92f84dd742c', 'en', 'Five, six, seven.', null),
