  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'en', 'Five-zero-one, two-three-four, five-six-seven. Right?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'es', 'Cinco-cero-uno, dos-tres-cuatro, cinco-seis-siete. ¿Correcto?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'fr', 'Cinq-zéro-un, deux-trois-quatre, cinq-six-sept. C''est bien ça ?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'de', 'Fünf-null-eins, zwei-drei-vier, fünf-sechs-sieben. Richtig?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'it', 'Cinque-zero-uno, due-tre-quattro, cinque-sei-sette. Giusto?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'pt', 'Cinco-zero-um, dois-três-quatro, cinco-seis-sete. Certo?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'ru', 'Пять-ноль-один, два-три-четыре, пять-шесть-семь. Верно?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'uk', 'П''ять-нуль-один, два-три-чотири, п''ять-шість-сім. Правильно?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'be', 'Пяць-нуль-адзін, два-тры-чатыры, пяць-шэсць-сем. Правільна?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'pl', 'Pięćset jeden, dwieście trzydzieści cztery, pięćset sześćdziesiąt siedem. Tak?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'tr', 'Beş-sıfır-bir, iki-üç-dört, beş-altı-yedi. Doğru mu?', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'zh', '五零一，二三四，五六七。对吗？', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'zh-Hant', '五零一、二三四、五六七。對嗎？', null),
