  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'ar', 'خمسة صفر واحد، اثنان ثلاثة أربعة، خمسة ستة سبعة. صحيح؟', null),
  ('84e0ee41-15ed-5e2e-bae6-c1dbd83e45d9', 'hi', 'पाँच-शून्य-एक, दो-तीन-चार, पाँच-छह-सात। सही है?', null),
