  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'pl', 'Zapytaj o znaczenie i pisownię słowa', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'ru', 'Спросить значение и написание слова', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'uk', 'Запитати значення й написання слова', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'en', 'Ask what a word means and how it''s spelled', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'es', 'Pregunta qué significa una palabra y cómo se escribe', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'fr', 'Demande le sens d''un mot et comment il s''écrit', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'de', 'Frag, was ein Wort bedeutet und wie man es schreibt', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'it', 'Chiedi cosa significa una parola e come si scrive', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'pt', 'Pergunta o que significa uma palavra e como se escreve', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'be', 'Спытаць значэнне і напісанне слова', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'tr', 'Bir kelimenin anlamını ve nasıl yazıldığını sor', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'zh', '问问一个词的意思和写法', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'zh-Hant', '問問一個字的意思和寫法', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'ja', '単語の意味とつづりを聞いてみよう', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'ar', 'السؤال عن معنى الكلمة وطريقة كتابتها', null),
  ('cf65cda5-6a27-5cf1-b61e-02fd55278762', 'hi', 'किसी शब्द का मतलब और स्पेलिंग पूछें', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'ru', 'ł читается как английское w, ó — как «у», rz и ż звучат одинаково. Поэтому даже поляки спрашивают, как пишется слово.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'uk', 'ł читається як англійське w, ó — як «у», rz і ż звучать однаково. Тому навіть поляки питають, як пишеться слово.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'en', 'ł sounds like English w, ó like “oo”, and rz and ż sound the same — even Poles ask how a word is spelled.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'es', 'ł suena como la w inglesa, ó como «u», y rz y ż suenan igual: hasta los polacos preguntan cómo se escribe una palabra.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'fr', 'ł se prononce comme « ou » dans « oui », ó comme « ou », et rz et ż se prononcent pareil — même les Polonais demandent comment un mot s''écrit.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'de', 'ł klingt wie das englische w, ó wie „u“, und rz und ż klingen gleich – deshalb fragen sogar Polen, wie man ein Wort schreibt.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'it', 'ł si pronuncia come la «u» di «uomo», ó come «u», e rz e ż suonano uguali: perfino i polacchi chiedono come si scrive una parola.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'pt', 'ł soa como o w inglês, ó como «u», e rz e ż soam igual — até os polacos perguntam como se escreve uma palavra.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'be', 'ł чытаецца як беларускае «ў», ó — як «у», а rz і ż гучаць аднолькава, як «ж». Таму нават палякі пытаюцца, як пішацца слова.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'tr', 'ł İngilizcedeki w gibi, ó “u” gibi okunur; rz ile ż ise aynı ses, Türkçedeki “j” gibi. Bu yüzden Polonyalılar bile bir kelimenin nasıl yazıldığını sorar.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'zh', 'ł 读起来像英语的 w，ó 像“乌”，rz 和 ż 发音相同——所以连波兰人也常问一个词怎么写。', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'zh-Hant', 'ł 讀起來像英文的 w，ó 像「烏」，rz 和 ż 發音相同——所以連波蘭人也常問一個字怎麼寫。', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'ja', 'ł は英語の w、ó は「ウ」のように読み、rz と ż は同じ音です。だからポーランド人でも、単語のつづりを聞き合います。', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'ar', 'يُنطق ł مثل w الإنجليزية (و)، و ó مثل الواو الممدودة في «نور»، أما rz و ż فيُنطقان بالطريقة نفسها، ولهذا يسأل حتى البولنديون عن كيفية كتابة الكلمة.', null),
  ('6bb44967-2149-56f6-9326-6ebb854e6ff3', 'hi', 'ł अंग्रेज़ी के w जैसा सुनाई देता है, ó “उ” जैसा, और rz और ż एक जैसे (लगभग “झ़”) सुनाई देते हैं — इसलिए पोलिश लोग भी पूछते हैं कि शब्द कैसे लिखा जाता है।', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'pl', 'Patrz, tam jest napis „Wyprzedaż”.', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'ru', 'Смотри, там написано «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'uk', 'Дивись, там напис «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'en', 'Look, the sign says “Wyprzedaż”.', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'es', 'Mira, ese cartel dice «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'fr', 'Regarde, là-bas, c''est écrit « Wyprzedaż ».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'de', 'Schau, da steht „Wyprzedaż“.', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'it', 'Guarda, lì c''è scritto «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'pt', 'Olha, aquele letreiro diz «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'be', 'Глядзі, там напісана «Wyprzedaż».', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'tr', 'Bak, orada “Wyprzedaż” yazıyor.', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'zh', '你看，那边的牌子上写着“Wyprzedaż”。', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'zh-Hant', '你看，那邊的招牌上寫著「Wyprzedaż」。', '妳看，那邊的招牌上寫著「Wyprzedaż」。'),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'ja', '見て、あそこに「Wyprzedaż」って書いてあるよ。', null),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'ar', 'انظرْ، هناك لافتة مكتوب عليها «Wyprzedaż».', 'انظري، هناك لافتة مكتوب عليها «Wyprzedaż».'),
  ('81bc774a-67cc-5495-afbe-210932d0fb2c', 'hi', 'देखो, वहाँ लिखा है “Wyprzedaż”।', null),
