  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'tr', 'Bu ne demek?', null),
  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'zh', '这是什么意思？', null),
  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'zh-Hant', '這是什麼意思？', null),
  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'ja', 'どういう意味？', null),
  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'ar', 'ماذا يعني هذا؟', null),
  ('e1f48f29-0902-5b2f-9f53-e0483e6bca6a', 'hi', 'इसका क्या मतलब है?', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'pl', 'To znaczy, że wszystko jest taniej.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'ru', 'Это значит, что всё дешевле.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'uk', 'Це означає, що все дешевше.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'en', 'It means everything is cheaper.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'es', 'Significa que todo está más barato.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'fr', 'Ça veut dire que tout est moins cher.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'de', 'Das heißt, dass alles billiger ist.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'it', 'Vuol dire che tutto costa meno.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'pt', 'Significa que está tudo mais barato.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'be', 'Гэта значыць, што ўсё таннейшае.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'tr', 'Her şey daha ucuz demek.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'zh', '意思是所有东西都变便宜了。', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'zh-Hant', '意思是所有東西都變便宜了。', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'ja', '全部安くなってるってことだよ。', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'ar', 'يعني أن كل شيء أصبح أرخص.', null),
  ('aa56547b-a595-569c-9fc4-520601b9eb8f', 'hi', 'इसका मतलब है कि सब कुछ सस्ता हो गया है।', null),
  ('fd68dcb3-b0c9-5e12-8af6-52ce93d7c2da', 'pl', 'Aha! A jak to się pisze?', null),
  ('fd68dcb3-b0c9-5e12-8af6-52ce93d7c2da', 'ru', 'А! А как это пишется?', null),
