  ('fd68dcb3-b0c9-5e12-8af6-52ce93d7c2da', 'ja', 'なるほど！で、どうつづるの？', null),
  ('fd68dcb3-b0c9-5e12-8af6-52ce93d7c2da', 'ar', 'آه! وكيف يُكتب هذا؟', null),
  ('fd68dcb3-b0c9-5e12-8af6-52ce93d7c2da', 'hi', 'अच्छा! और इसे लिखते कैसे हैं?', null),
  ('0fb80870-a0fa-57f0-8837-372d2376aac0', 'pl', 'Z „rz” i z kropką nad „z” na końcu.', null),
