  ('0fb80870-a0fa-57f0-8837-372d2376aac0', 'ja', '「rz」で、最後の「z」の上に点がつくよ。', null),
  ('0fb80870-a0fa-57f0-8837-372d2376aac0', 'ar', 'بـ«rz»، وبنقطة فوق «z» في آخرها.', null),
