  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'ru', 'Чтение: cz — твёрдое «ч», sz — «ш», ś и si — мягкое «щь». Cześć и siema — только для друзей.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'uk', 'Читання: cz — тверде «ч», sz — «ш», ś і si — м''яке «щь». Cześć і siema — лише для друзів.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'en', 'Reading: cz sounds like “ch”, sz like “sh”, ś and si like a soft “sh”. Cześć and siema are only for friends.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'es', 'Lectura: cz suena como «ch», sz como la «sh» inglesa, y ś y si como una «sh» más suave. Cześć y siema son solo para amigos.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'fr', 'Lecture : cz se prononce « tch », sz « ch », ś et si comme un « ch » plus doux. Cześć et siema, c''est seulement entre amis.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'de', 'Aussprache: cz klingt wie „tsch“, sz wie „sch“, ś und si wie ein weiches „sch“. Cześć und siema sagt man nur zu Freunden.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'it', 'Lettura: cz si legge come la «c» di «ciao», sz come «sc» di «scena», ś e si come una «sc» più morbida. Cześć e siema si usano solo tra amici.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'pt', 'Leitura: cz soa como «tch», sz como o «ch» de «chave», e ś e si como um «ch» mais suave. Cześć e siema são só para amigos.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'be', 'Чытанне: cz — «ч», sz — «ш», ś і si — мяккі гук, падобны да «сь». Cześć і siema — толькі для сяброў.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'tr', 'Okunuş: cz “ç” gibi, sz “ş” gibi, ś ve si ise yumuşak bir “ş” gibi okunur. Cześć ve siema yalnızca arkadaşlar arasında kullanılır.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'zh', '读音：cz 像拼音的 ch，sz 像 sh，ś 和 si 像 x。Cześć 和 siema 只在朋友之间用。', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'zh-Hant', '讀音：cz 像注音的「ㄔ」，sz 像「ㄕ」，ś 和 si 像「ㄒ」。Cześć 和 siema 只能跟朋友說。', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'ja', '読み方：cz は硬めの「チ」、sz は「シュ」、ś と si はやわらかい「シ」のような音です。Cześć と siema は友だち同士でだけ使います。', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'ar', 'القراءة: يُنطق cz مثل «تش»، و sz مثل «ش»، و ś و si مثل «ش» مُرقّقة. أما Cześć و siema فللأصدقاء فقط.', null),
  ('f4bb0077-167c-56f1-b95b-30e54c4e5762', 'hi', 'पढ़ना: cz “च” जैसा, sz “श” जैसा, ś और si नरम “श” जैसे। Cześć और siema सिर्फ़ दोस्तों के लिए हैं।', null),
