  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'uk', 'Привіт! Добре, а в тебе?', null),
  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'en', 'Hi! Good, and you?', null),
  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'es', '¡Hola! Bien, ¿y tú?', null),
