  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'de', 'Hallo! Gut, und dir?', null),
  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'it', 'Ciao! Bene, e tu?', null),
  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'pt', 'Olá! Bem, e tu?', null),
