  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'zh-Hant', '嗨！還不錯，你呢？', null),
  ('2ca38942-3e1d-5ead-a791-6f2f80abe6ae', 'ja', 'やあ！元気だよ、そっちは？', null),
