  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'ru', 'Носовые: ą звучит примерно как «он», ę — как «эн». В конце слова ę почти не слышно: dziękuję ≈ «дженькуе».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'uk', 'Носові: ą звучить приблизно як «он», ę — як «ен». У кінці слова ę майже не чути: dziękuję ≈ «дженькує».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'en', 'Nasal vowels: ą sounds roughly like “on”, ę like “en”. At the end of a word ę is barely heard: dziękuję ≈ “jen-koo-yeh”.', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'es', 'Vocales nasales: ą suena más o menos como «on», ę como «en». Al final de palabra la ę apenas se oye: dziękuję ≈ «dyen-kú-ye».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'fr', 'Voyelles nasales : ą se prononce à peu près « on », ę comme « in ». En fin de mot, ę s''entend à peine : dziękuję ≈ « djèn-kou-yé ».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'de', 'Nasalvokale: ą klingt ungefähr wie „on“, ę wie „en“. Am Wortende hört man ę kaum: dziękuję ≈ „dschen-ku-je“.', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'it', 'Vocali nasali: ą si pronuncia più o meno «on», ę «en». A fine parola la ę quasi non si sente: dziękuję ≈ «gen-cu-ie».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'pt', 'Vogais nasais: ą soa mais ou menos como «om», ę como «em». No fim da palavra, o ę quase não se ouve: dziękuję ≈ «djen-cú-ie».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'be', 'Насавыя: ą гучыць прыкладна як «он», ę — як «эн». У канцы слова ę амаль не чуваць: dziękuję ≈ «джэнькуе».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'tr', 'Genizden gelen ünlüler: ą kabaca “on”, ę ise “en” gibi okunur. Kelime sonunda ę neredeyse duyulmaz: dziękuję ≈ “cenkuye”.', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'zh', '鼻化元音：ą 大致像“翁”，ę 像“恩”。ę 在词尾几乎听不出来：dziękuję ≈ “坚-酷-耶”。', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'zh-Hant', '鼻化母音：ą 大致像「翁」，ę 像「恩」。ę 在字尾幾乎聽不出來：dziękuję ≈「堅-酷-耶」。', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'ja', '鼻母音：ą はだいたい「オン」、ę は「エン」のように聞こえます。語末の ę はほとんど聞こえません：dziękuję ≈「ジェンクイェ」。', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'ar', 'الحروف الأنفية: يُنطق ą تقريبًا مثل «أون»، و ę مثل «إن». وفي آخر الكلمة لا يكاد ę يُسمع: dziękuję ≈ «جين-كو-يه».', null),
  ('a05cd96d-2706-5478-98a3-a509f2534cfe', 'hi', 'नासिक्य स्वर: ą लगभग “ओं” जैसा सुनाई देता है, ę “एं” जैसा। शब्द के आख़िर में ę मुश्किल से सुनाई देता है: dziękuję ≈ “जेन-कू-ये”।', null),
  ('02ff82c4-3588-5e20-af11-e943f1a5242c', 'pl', 'Pomóc ci z tą torbą?', null),
