  ('21bab09f-b9a3-5962-b3ab-c192315ac550', 'pl', 'Przywitaj się i pożegnaj grzecznie', null),
  ('21bab09f-b9a3-5962-b3ab-c192315ac550', 'ru', 'Вежливо поздороваться и попрощаться', null),
  ('21bab09f-b9a3-5962-b3ab-c192315ac550', 'uk', 'Ввічливо привітатися й попрощатися', null),
  ('21bab09f-b9a3-5962-b3ab-c192315ac550', 'en', 'Say hello and goodbye politely', null),
