  ('21bab09f-b9a3-5962-b3ab-c192315ac550', 'hi', 'शिष्टता से नमस्ते और अलविदा कहें', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'ru', 'Ударение в польском почти всегда на предпоследний слог: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'uk', 'Наголос у польській майже завжди на передостанньому складі: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'en', 'Polish stress almost always falls on the second-to-last syllable: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'es', 'En polaco el acento casi siempre cae en la penúltima sílaba: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'fr', 'En polonais, l''accent tombe presque toujours sur l''avant-dernière syllabe : do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'de', 'Im Polnischen liegt die Betonung fast immer auf der vorletzten Silbe: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'it', 'In polacco l''accento cade quasi sempre sulla penultima sillaba: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'pt', 'Em polaco, a sílaba tónica é quase sempre a penúltima: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'be', 'Націск у польскай мове амаль заўсёды падае на перадапошні склад: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'tr', 'Lehçede vurgu neredeyse her zaman sondan bir önceki hecededir: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'zh', '波兰语的重音几乎总在倒数第二个音节上：do wi-DZE-nia、dzię-KU-ję、War-SZA-wa。', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'zh-Hant', '波蘭語的重音幾乎都落在倒數第二個音節：do wi-DZE-nia、dzię-KU-ję、War-SZA-wa。', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'ja', 'ポーランド語のアクセントは、ほぼいつも後ろから2番目の音節にあります：do wi-DZE-nia, dzię-KU-ję, War-SZA-wa。', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'ar', 'يقع النبر في البولندية دائمًا تقريبًا على المقطع قبل الأخير: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('5aaa9c09-ad5d-5926-b74b-bebf74121356', 'hi', 'पोलिश में ज़ोर लगभग हमेशा आख़िरी से पहले वाले सिलेबल पर पड़ता है: do wi-DZE-nia, dzię-KU-ję, War-SZA-wa.', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'pl', 'Dzień dobry! Do pracy?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'ru', 'Здравствуйте! На работу?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'uk', 'Добрий день! На роботу?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'en', 'Good morning! Off to work?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'es', '¡Buenos días! ¿Al trabajo?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'fr', 'Bonjour ! Vous allez au travail ?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'de', 'Guten Morgen! Zur Arbeit?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'it', 'Buongiorno! Va al lavoro?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'pt', 'Bom dia! Para o trabalho?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'be', 'Добры дзень! На працу?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'tr', 'Günaydın! İşe mi gidiyorsunuz?', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'zh', '早上好！您去上班啊？', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'zh-Hant', '早安！您要去上班嗎？', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'ja', 'おはようございます！お仕事ですか？', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'ar', 'صباح الخير! إلى العمل؟', null),
  ('656ad173-e7b2-57a3-af38-f5be80d8d5df', 'hi', 'नमस्ते! काम पर जा रहे हैं?', 'नमस्ते! काम पर जा रही हैं?'),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'pl', 'Dzień dobry! Tak, do pracy.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'ru', 'Здравствуйте! Да, на работу.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'uk', 'Добрий день! Так, на роботу.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'en', 'Good morning! Yes, off to work.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'es', '¡Buenos días! Sí, al trabajo.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'fr', 'Bonjour ! Oui, je vais au travail.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'de', 'Guten Morgen! Ja, zur Arbeit.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'it', 'Buongiorno! Sì, vado al lavoro.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'pt', 'Bom dia! Sim, para o trabalho.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'be', 'Добры дзень! Так, на працу.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'tr', 'Günaydın! Evet, işe gidiyorum.', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'zh', '早上好！对，去上班。', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'zh-Hant', '早安！對，去上班。', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'ja', 'おはようございます！はい、仕事です。', null),
  ('cdd85073-0e6f-58a8-b470-51e3e52e1892', 'ar', 'صباح الخير! نعم، إلى العمل.', null),
