  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'en', 'Have a nice day, then!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'es', '¡Pues que tenga un buen día!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'fr', 'Alors, bonne journée !', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'de', 'Dann einen schönen Tag!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'it', 'Allora buona giornata!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'pt', 'Então tenha um bom dia!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'be', 'Тады прыемнага дня!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'tr', 'O zaman iyi günler!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'zh', '那祝您今天愉快！', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'zh-Hant', '那祝您今天愉快！', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'ja', 'では、よい一日を！', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'ar', 'إذن، يومًا سعيدًا!', null),
  ('2833efdc-fc51-595f-a078-fdf1969e41ef', 'hi', 'तो आपका दिन अच्छा रहे!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'pl', 'Dziękuję, nawzajem! Do widzenia!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'ru', 'Спасибо, и вам! До свидания!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'uk', 'Дякую, навзаєм! До побачення!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'en', 'Thank you, you too! Goodbye!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'es', '¡Gracias, igualmente! ¡Adiós!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'fr', 'Merci, vous aussi ! Au revoir !', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'de', 'Danke, gleichfalls! Auf Wiedersehen!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'it', 'Grazie, altrettanto! Arrivederci!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'pt', 'Obrigado, igualmente! Adeus!', 'Obrigada, igualmente! Adeus!'),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'be', 'Дзякуй, і вам таксама! Да пабачэння!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'tr', 'Teşekkür ederim, size de! Hoşça kalın!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'zh', '谢谢，您也是！再见！', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'zh-Hant', '謝謝，您也是！再見！', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'ja', 'ありがとうございます、そちらも！さようなら！', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'ar', 'شكرًا، ولحضرتكِ أيضًا! مع السلامة!', null),
  ('f1e1dfd5-f588-5357-ba17-585551f2f022', 'hi', 'शुक्रिया, आपका भी! अलविदा!', null),
