  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'ru', 'После «miłego» слово меняет окончание: dzień → dnia. Запоминай фразу целиком.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'uk', 'Після «miłego» слово змінює закінчення: dzień → dnia. Запам''ятовуй фразу цілком.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'en', 'After “miłego” the word changes its ending: dzień → dnia. Learn the phrase as a whole.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'es', 'Después de «miłego», la palabra cambia de terminación: dzień → dnia. Apréndete la frase entera.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'fr', 'Après « miłego », le mot change de terminaison : dzień → dnia. Apprends l''expression en entier.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'de', 'Nach „miłego“ ändert das Wort seine Endung: dzień → dnia. Lern den Ausdruck als Ganzes.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'it', 'Dopo «miłego» la parola cambia desinenza: dzień → dnia. Impara l''espressione intera.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'pt', 'Depois de «miłego», a palavra muda de terminação: dzień → dnia. Aprende a frase inteira.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'be', 'Пасля «miłego» слова мяняе канчатак: dzień → dnia. Запамінай фразу цалкам.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'tr', '“miłego” kelimesinden sonra gelen kelimenin sonu değişir: dzień → dnia. İfadeyi bir bütün olarak öğren.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'zh', '在“miłego”后面，这个词的词尾会变：dzień → dnia。把整句话一起记住。', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'zh-Hant', '在「miłego」後面，這個字的字尾會變：dzień → dnia。整句一起記住就好。', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'ja', '「miłego」のあとでは語尾が変わります：dzień → dnia。フレーズごと覚えましょう。', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'ar', 'بعد «miłego» تتغير نهاية الكلمة: dzień → dnia. الأفضل حفظ العبارة كاملة.', null),
  ('9d71697a-e79a-5fc2-9553-feaf4dbf6def', 'hi', '“miłego” के बाद शब्द का अंत बदल जाता है: dzień → dnia। पूरा वाक्यांश एक साथ याद करें।', null),
