  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'pl', 'Która godzina?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'ru', 'Который час?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'uk', 'Котра година?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'en', 'What time is it?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'es', '¿Qué hora es?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'fr', 'Quelle heure est-il ?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'de', 'Wie spät ist es?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'it', 'Che ore sono?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'pt', 'Que horas são?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'be', 'Каторая гадзіна?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'tr', 'Saat kaç?', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'zh', '现在几点？', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'zh-Hant', '現在幾點？', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'ja', '今何時？', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'ar', 'كم الساعة؟', null),
  ('0c0e193e-0962-5408-b193-87605fca2b9c', 'hi', 'कितने बजे हैं?', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'pl', 'Zapytaj o godzinę i umów się', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'ru', 'Спросить время и договориться', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'uk', 'Запитати час і домовитися', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'en', 'Ask the time and make plans', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'es', 'Pregunta la hora y queda con alguien', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'fr', 'Demande l''heure et fixe un rendez-vous', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'de', 'Frag nach der Uhrzeit und verabrede dich', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'it', 'Chiedi l''ora e fissa un appuntamento', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'pt', 'Pergunta as horas e marca um encontro', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'be', 'Спытаць, каторая гадзіна, і дамовіцца', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'tr', 'Saati sor ve buluşma ayarla', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'zh', '问问时间，约好见面', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'zh-Hant', '問問時間，約好見面', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'ja', '時間を聞いて、約束しよう', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'ar', 'السؤال عن الوقت وتحديد موعد', null),
  ('1cef8769-a568-5dfb-b6c2-5b47fd8a96d9', 'hi', 'समय पूछें और मिलने का प्लान बनाएँ', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'ru', 'Ложный друг: godzina — это «час», а «время» — czas. Часы называют порядковыми числами: piąta — «пятая», то есть 5 часов.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'uk', 'Godzina — це «година», а «час» — czas, як і українською. Години називають порядковими числівниками: piąta — «п''ята», тобто п''ята година (5:00).', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'en', 'Careful: godzina means “hour”, and “time” is czas. Hours use ordinal numbers: piąta — “the fifth”, i.e. 5 o''clock.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'es', 'Ojo: godzina significa «hora», y «tiempo» es czas. Las horas se dicen con ordinales: piąta, «la quinta», es decir, las cinco.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'fr', 'Attention : godzina, c''est « l''heure », et le « temps », c''est czas. Pour dire l''heure, on utilise les ordinaux : piąta — « la cinquième », c''est-à-dire 5 heures.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'de', 'Vorsicht: godzina heißt „Stunde“, und „Zeit“ ist czas. Uhrzeiten sagt man mit Ordnungszahlen: piąta – „die fünfte“, also 5 Uhr.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'it', 'Attenzione: godzina vuol dire «ora», mentre «tempo» si dice czas. Per le ore si usano gli ordinali: piąta — «la quinta», cioè le 5.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'pt', 'Atenção: godzina quer dizer «hora», e «tempo» é czas. As horas dizem-se com ordinais: piąta — «a quinta», ou seja, as cinco.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'be', 'godzina — гэта «гадзіна», а czas — «час», як і па-беларуску. Гадзіны называюць парадкавымі лікамі: piąta — «пятая», гэта значыць роўна 5 гадзін (не блытай з беларускім «пятая гадзіна», калі яшчэ няма пяці).', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'tr', 'Dikkat: godzina “saat” (60 dakika) demektir, “zaman” ise czas. Saatler sıra sayılarıyla söylenir: piąta — “beşinci”, yani saat 5.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'zh', '注意：godzina 是“小时”，“时间”是 czas。说几点要用序数词：piąta 是“第五”，也就是 5 点。', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'zh-Hant', '注意：godzina 是「小時」，「時間」是 czas。說幾點要用序數：piąta 是「第五」，也就是 5 點。', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'ja', '注意：godzina は「1時間」のことで、「時間（とき）」そのものは czas です。時刻は序数で言います：piąta は「5番目」、つまり5時です。', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'ar', 'تنبيه: godzina تعني «ساعة» (60 دقيقة)، أما «الوقت» فهو czas. وتُقال الساعات بالأعداد الترتيبية: piąta تعني «الخامسة»، أي الساعة 5.', null),
  ('c2bf65fa-e0f5-5bff-abdb-07af205e79f4', 'hi', 'ध्यान दें: godzina का मतलब “घंटा” है, और “समय” होता है czas। घंटे क्रमसूचक संख्याओं से बताए जाते हैं: piąta — “पाँचवाँ (घंटा)”, यानी 5 बजे।', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'pl', 'Idziemy wieczorem do kina?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'ru', 'Идём вечером в кино?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'uk', 'Ідемо ввечері в кіно?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'en', 'Shall we go to the cinema tonight?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'es', '¿Vamos al cine esta noche?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'fr', 'On va au cinéma ce soir ?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'de', 'Gehen wir heute Abend ins Kino?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'it', 'Andiamo al cinema stasera?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'pt', 'Vamos ao cinema logo à noite?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'be', 'Пойдзем увечары ў кіно?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'tr', 'Bu akşam sinemaya gidelim mi?', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'zh', '晚上我们去看电影吧？', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'zh-Hant', '晚上我們去看電影好不好？', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'ja', '今夜、映画に行かない？', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'ar', 'هل نذهب إلى السينما هذا المساء؟', null),
  ('0b4b4664-f223-5506-b952-c0f7b4b3fd35', 'hi', 'आज शाम सिनेमा चलें?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'pl', 'Tak! O której?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'ru', 'Да! Во сколько?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'uk', 'Так! О котрій?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'en', 'Yes! What time?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'es', '¡Sí! ¿A qué hora?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'fr', 'Oui ! À quelle heure ?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'de', 'Ja! Um wie viel Uhr?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'it', 'Sì! A che ora?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'pt', 'Sim! A que horas?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'be', 'Так! А якой гадзіне?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'tr', 'Evet! Saat kaçta?', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'zh', '好啊！几点？', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'zh-Hant', '好啊！幾點？', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'ja', 'うん！何時に？', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'ar', 'نعم! في أي ساعة؟', null),
  ('99a744fd-ef38-5a7e-a0fb-dd9e9c539e90', 'hi', 'हाँ! कितने बजे?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'pl', 'O siódmej. A która jest teraz?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'ru', 'В семь. А сейчас который час?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'uk', 'О сьомій. А котра зараз?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'en', 'At seven. What time is it now?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'es', 'A las siete. ¿Y qué hora es ahora?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'fr', 'À sept heures. Et là, il est quelle heure ?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'de', 'Um sieben. Und wie spät ist es jetzt?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'it', 'Alle sette. E adesso che ore sono?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'pt', 'Às sete. E que horas são agora?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'be', 'А сёмай. А колькі цяпер?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'tr', 'Yedide. Peki şimdi saat kaç?', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'zh', '七点。那现在几点了？', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'zh-Hant', '七點。那現在幾點？', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'ja', '7時。で、今何時？', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'ar', 'في السابعة. وكم الساعة الآن؟', null),
  ('283989e2-6cd4-5962-84f9-4aedb18d3e00', 'hi', 'सात बजे। और अभी कितने बजे हैं?', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'pl', 'Jest piąta.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'ru', 'Пять часов.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'uk', 'П''ята година.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'en', 'It''s five o''clock.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'es', 'Son las cinco.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'fr', 'Il est cinq heures.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'de', 'Es ist fünf Uhr.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'it', 'Sono le cinque.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'pt', 'São cinco horas.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'be', 'Пяць гадзін.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'tr', 'Saat beş.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'zh', '现在五点。', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'zh-Hant', '現在五點。', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'ja', '5時だよ。', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'ar', 'الساعة الخامسة.', null),
  ('fa629651-8d57-5b95-b6dc-cb754a136101', 'hi', 'पाँच बजे हैं।', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'pl', 'To mamy jeszcze dwie godziny!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'ru', 'Значит, у нас ещё два часа!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'uk', 'Значить, у нас ще дві години!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'en', 'So we''ve still got two hours!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'es', '¡Pues aún tenemos dos horas!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'fr', 'Alors on a encore deux heures !', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'de', 'Dann haben wir noch zwei Stunden!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'it', 'Allora abbiamo ancora due ore!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'pt', 'Então ainda temos duas horas!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'be', 'Значыць, у нас яшчэ дзве гадзіны!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'tr', 'O zaman daha iki saatimiz var!', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'zh', '那我们还有两个小时！', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'zh-Hant', '那我們還有兩個小時！', null),
  ('6a31cf19-611a-5f8d-8f8d-4b147abcc64e', 'ja', 'じゃあ、まだ2時間あるね！', null),
