  ('a3e0e24c-f441-597d-9d22-1dc34247e58d', 'fr', 'Il est cinq heures.', null),
  ('a3e0e24c-f441-597d-9d22-1dc34247e58d', 'de', 'Es ist fünf Uhr.', null),
