  ('a3e0e24c-f441-597d-9d22-1dc34247e58d', 'hi', 'पाँच बजे हैं।', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'ru', 'Не «pięć», а «piąta»: часы называют порядковым числом — «пятая» (godzina).', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'uk', 'Не «pięć», а «piąta»: години називають як «п''ята (година)».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'en', 'Not “pięć” but “piąta”: hours are said as “the fifth (hour)”.', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'es', 'No «pięć», sino «piąta»: las horas se dicen como «la quinta (hora)».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'fr', 'Pas « pięć », mais « piąta » : on dit l''heure comme « la cinquième (heure) ».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'de', 'Nicht „pięć“, sondern „piąta“: Uhrzeiten sagt man als „die fünfte (Stunde)“.', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'it', 'Non «pięć» ma «piąta»: le ore si dicono come «la quinta (ora)».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'pt', 'Não «pięć», mas «piąta»: as horas dizem-se como «a quinta (hora)».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'be', 'Не «pięć», а «piąta»: гадзіны называюць як «пятая (гадзіна)».', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'tr', '“pięć” değil, “piąta”: saatler “beşinci (saat)” diye söylenir.', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'zh', '不是“pięć”，而是“piąta”：几点要说成“第五（个钟点）”。', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'zh-Hant', '不是「pięć」，而是「piąta」：幾點要說成「第五（個鐘頭）」。', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'ja', '「pięć」ではなく「piąta」：時刻は「5番目（の時間）」のように言います。', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'ar', 'ليس «pięć» بل «piąta»: تُقال الساعات بصيغة «الخامسة» تمامًا كما في العربية.', null),
  ('9a0372f5-c807-5197-83d8-c9397fe20d11', 'hi', '“pięć” नहीं, बल्कि “piąta”: घंटे “पाँचवाँ (घंटा)” की तरह बताए जाते हैं।', null),
