  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'ru', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Номер часто диктуют группами по три цифры: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'uk', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Номер часто диктують групами по три цифри: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'en', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Phone numbers are often read in groups of three: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'es', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Los números de teléfono se suelen decir en grupos de tres: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'fr', '0–10 : zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Les numéros de téléphone se lisent souvent par groupes de trois : 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'de', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Telefonnummern liest man oft in Dreiergruppen: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'it', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. I numeri di telefono si leggono spesso a gruppi di tre: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'pt', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Os números de telefone dizem-se muitas vezes em grupos de três: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'be', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Нумар часта дыктуюць групамі па тры лічбы: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'tr', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. Telefon numaraları genellikle üçerli gruplar hâlinde okunur: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'zh', '0–10：zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć。电话号码常常三位一组来读：501 234 567。', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'zh-Hant', '0–10：zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć。電話號碼常常三個數字一組來唸：501 234 567。', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'ja', '0–10：zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć。電話番号は3けたずつ区切って読むことがよくあります：501 234 567。', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'ar', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć. وكثيرًا ما تُقرأ أرقام الهاتف في مجموعات من ثلاثة: 501 234 567.', null),
  ('3f5489c4-d20d-5441-bd34-f1d23db64d8e', 'hi', '0–10: zero, jeden, dwa, trzy, cztery, pięć, sześć, siedem, osiem, dziewięć, dziesięć। फ़ोन नंबर अक्सर तीन-तीन अंकों के समूहों में बोले जाते हैं: 501 234 567।', null),
  ('eaadbe32-c9b1-53b4-b7a1-a1da06dd0794', 'pl', 'Proszę podać numer telefonu.', null),
  ('eaadbe32-c9b1-53b4-b7a1-a1da06dd0794', 'ru', 'Назовите, пожалуйста, номер телефона.', null),
