  ('540d535f-56e1-5c14-ac9f-f62cbf6e9b9c', 'zh', '五、零、一、二、三、四。', null),
  ('540d535f-56e1-5c14-ac9f-f62cbf6e9b9c', 'zh-Hant', '五、零、一、二、三、四。', null),
  ('540d535f-56e1-5c14-ac9f-f62cbf6e9b9c', 'ja', 'ご、ゼロ、いち、に、さん、よん。', null),
  ('540d535f-56e1-5c14-ac9f-f62cbf6e9b9c', 'ar', 'خمسة، صفر، واحد، اثنان، ثلاثة، أربعة.', null),
  ('540d535f-56e1-5c14-ac9f-f62cbf6e9b9c', 'hi', 'पाँच, शून्य, एक, दो, तीन, चार।', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'pl', 'Dobrze. A dalej?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'ru', 'Хорошо. А дальше?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'uk', 'Добре. А далі?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'en', 'OK. And then?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'es', 'Bien. ¿Y luego?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'fr', 'Bien. Et ensuite ?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'de', 'Gut. Und weiter?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'it', 'Bene. E poi?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'pt', 'Muito bem. E a seguir?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'be', 'Добра. А далей?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'tr', 'Tamam. Devamı?', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'zh', '好的。然后呢？', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'zh-Hant', '好的。然後呢？', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'ja', 'はい。それから？', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'ar', 'حسنًا. وبعد ذلك؟', null),
  ('ac890f9a-a751-55b0-9741-9987a386a5a3', 'hi', 'ठीक है। और आगे?', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'pl', 'Pięć, sześć, siedem.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'ru', 'Пять, шесть, семь.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'uk', 'П''ять, шість, сім.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'en', 'Five, six, seven.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'es', 'Cinco, seis, siete.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'fr', 'Cinq, six, sept.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'de', 'Fünf, sechs, sieben.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'it', 'Cinque, sei, sette.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'pt', 'Cinco, seis, sete.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'be', 'Пяць, шэсць, сем.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'tr', 'Beş, altı, yedi.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'zh', '五、六、七。', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'zh-Hant', '五、六、七。', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'ja', 'ご、ろく、なな。', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'ar', 'خمسة، ستة، سبعة.', null),
  ('a9bf6ca8-4e83-5742-b9f6-5897f767a80d', 'hi', 'पाँच, छह, सात।', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'pl', 'Pięćset jeden, dwieście trzydzieści cztery, pięćset sześćdziesiąt siedem. Tak?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'ru', 'Пятьсот один, двести тридцать четыре, пятьсот шестьдесят семь. Верно?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'uk', 'П''ятсот один, двісті тридцять чотири, п''ятсот шістдесят сім. Так?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'en', 'Five hundred and one, two hundred and thirty-four, five hundred and sixty-seven. Right?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'es', 'Quinientos uno, doscientos treinta y cuatro, quinientos sesenta y siete. ¿Es así?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'fr', 'Cinq cent un, deux cent trente-quatre, cinq cent soixante-sept. C''est bien ça ?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'de', 'Fünfhunderteins, zweihundertvierunddreißig, fünfhundertsiebenundsechzig. Richtig?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'it', 'Cinquecentouno, duecentotrentaquattro, cinquecentosessantasette. Giusto?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'pt', 'Quinhentos e um, duzentos e trinta e quatro, quinhentos e sessenta e sete. Certo?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'be', 'Пяцьсот адзін, дзвесце трыццаць чатыры, пяцьсот шэсцьдзясят сем. Так?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'tr', 'Beş yüz bir, iki yüz otuz dört, beş yüz altmış yedi. Doğru mu?', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'zh', '五零一，二三四，五六七。对吗？', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'zh-Hant', '五零一，二三四，五六七。對嗎？', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'ja', 'ごひゃくいち、にひゃくさんじゅうよん、ごひゃくろくじゅうなな。よろしいですか？', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'ar', 'خمسمئة وواحد، مئتان وأربعة وثلاثون، خمسمئة وسبعة وستون. صحيح؟', null),
  ('b37c843a-65f4-5cf0-b30a-59c9078dc23d', 'hi', 'पाँच सौ एक, दो सौ चौंतीस, पाँच सौ सड़सठ। सही है?', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'pl', 'Tak, wszystko się zgadza.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'ru', 'Да, всё верно.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'uk', 'Так, усе правильно.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'en', 'Yes, that''s all correct.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'es', 'Sí, todo correcto.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'fr', 'Oui, tout est exact.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'de', 'Ja, das stimmt alles.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'it', 'Sì, è tutto giusto.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'pt', 'Sim, está tudo certo.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'be', 'Так, усё правільна.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'tr', 'Evet, hepsi doğru.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'zh', '对，全都没错。', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'zh-Hant', '對，全部都對。', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'ja', 'はい、全部合っています。', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'ar', 'نعم، كل شيء صحيح.', null),
  ('479392a0-cf40-5551-be8c-c71d886d0e5e', 'hi', 'जी हाँ, सब सही है।', null),
