  ('98136f65-a346-5361-aa81-0a486816a638', 'en', 'First names', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'es', 'Tutearse', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'fr', 'Se tutoyer', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'de', 'Per du', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'it', 'Darsi del tu', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'pt', 'Tratar por tu', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'be', 'На «ты»', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'tr', '“Sen” diye hitap', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'zh', '以“你”相称', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'zh-Hant', '以「你」相稱', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'ja', 'タメ口で', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'ar', 'رفع الكلفة', null),
  ('98136f65-a346-5361-aa81-0a486816a638', 'hi', '“आप” से “तुम”', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'pl', 'Przejdź z sąsiadem na ty', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'ru', 'Перейти на «ты» с соседом', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'uk', 'Перейти на «ти» із сусідом', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'en', 'Switch to first names with a neighbour', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'es', 'Empieza a tutear a tu vecino', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'fr', 'Passe au tutoiement avec un voisin', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'de', 'Wechsle mit dem Nachbarn zum Du', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'it', 'Passa al tu con un vicino', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'pt', 'Passa a tratar o vizinho por tu', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'be', 'Перайсці на «ты» з суседам', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'tr', 'Komşunla “sen” diye konuşmaya geç', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'zh', '和邻居改用“你”相称', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'zh-Hant', '和鄰居改用「你」相稱', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'ja', 'お隣さんとタメ口で話す仲になろう', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'ar', 'رفع الكلفة مع الجار', null),
  ('def664d3-4a11-5fa3-a2d1-2d1c200bd7ce', 'hi', 'पड़ोसी के साथ “आप” से “तुम” पर आएँ', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'ru', 'На «ты» обычно предлагает перейти старший или тот, кто выше по статусу. Самостоятельно предлагать это не принято — просто соглашайся: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'uk', 'На «ти» зазвичай пропонує перейти старший або той, хто вищий за статусом. Самостійно пропонувати це не прийнято — просто погоджуйся: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'en', 'Usually the older or more senior person offers first names. Don''t start it yourself — just agree: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'es', 'Normalmente es la persona mayor o de más rango quien propone tutearse. No lo propongas tú; basta con aceptar: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'fr', 'En général, c''est la personne la plus âgée ou la plus haut placée qui propose de se tutoyer. Ne le propose pas toi-même — accepte simplement : Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'de', 'Meist bietet die ältere oder ranghöhere Person das Du an. Fang nicht selbst damit an – stimm einfach zu: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'it', 'Di solito è la persona più anziana o di grado più alto a proporre di darsi del tu. Non proporlo tu — accetta e basta: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'pt', 'Normalmente é a pessoa mais velha ou com uma posição mais alta que propõe o tratamento por tu. Não sejas tu a começar — basta aceitar: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'be', 'Перайсці на «ты» звычайна прапануе старэйшы або той, хто вышэйшы па статусе. Не прапаноўвай гэтага першым — проста пагаджайся: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'tr', '“Sen” diye konuşmayı genellikle daha yaşlı ya da daha kıdemli olan önerir. Bunu kendin başlatma, sadece kabul et: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'zh', '通常由年长或地位较高的一方提出改用“你”。不要自己先提——对方提出时答应就好：Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'zh-Hant', '通常由年紀較大或地位較高的一方提議改用「你」。別自己先開口——對方提了，答應就好：Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'ja', 'ふつうは年上の人や立場が上の人のほうから、タメ口を提案します。自分からは言い出さず、同意すればOKです：Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'ar', 'عادةً ما يقترح الأكبر سنًّا أو الأعلى مكانةً رفع الكلفة. لا داعي للمبادرة بذلك، تكفي الموافقة: Jasne!', null),
  ('e92e3682-18ce-524b-8d18-c9e08171d4df', 'hi', 'आम तौर पर “तुम” पर आने का सुझाव उम्र या पद में बड़ा व्यक्ति देता है। ख़ुद शुरुआत न करें — बस हाँ कह दें: Jasne!', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'pl', 'Dzień dobry! Pan jest nowym sąsiadem?', 'Dzień dobry! Pani jest nową sąsiadką?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'ru', 'Здравствуйте! Вы наш новый сосед?', 'Здравствуйте! Вы наша новая соседка?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'uk', 'Добрий день! Ви наш новий сусід?', 'Добрий день! Ви наша нова сусідка?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'en', 'Hello! Are you our new neighbour?', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'es', '¡Buenos días! ¿Es usted el nuevo vecino?', '¡Buenos días! ¿Es usted la nueva vecina?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'fr', 'Bonjour ! Vous êtes notre nouveau voisin ?', 'Bonjour ! Vous êtes notre nouvelle voisine ?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'de', 'Guten Tag! Sind Sie der neue Nachbar?', 'Guten Tag! Sind Sie die neue Nachbarin?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'it', 'Buongiorno! Lei è il nostro nuovo vicino?', 'Buongiorno! Lei è la nostra nuova vicina?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'pt', 'Bom dia! O senhor é o novo vizinho?', 'Bom dia! A senhora é a nova vizinha?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'be', 'Добры дзень! Вы наш новы сусед?', 'Добры дзень! Вы наша новая суседка?'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'tr', 'Merhaba! Yeni komşu siz misiniz?', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'zh', '您好！您是新搬来的邻居吧？', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'zh-Hant', '您好！您是新搬來的鄰居嗎？', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'ja', 'こんにちは！新しいお隣さんですか？', null),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'ar', 'مرحبًا! هل حضرتكَ جارنا الجديد؟', 'مرحبًا! هل حضرتكِ جارتنا الجديدة؟'),
  ('9f537364-eacc-50a2-b760-913858d65ec2', 'hi', 'नमस्ते! क्या आप हमारे नए पड़ोसी हैं?', 'नमस्ते! क्या आप हमारी नई पड़ोसन हैं?'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'pl', 'Dzień dobry! Tak, jestem nowy.', 'Dzień dobry! Tak, jestem nowa.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'ru', 'Здравствуйте! Да, я новенький.', 'Здравствуйте! Да, я новенькая.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'uk', 'Добрий день! Так, я новенький.', 'Добрий день! Так, я новенька.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'en', 'Hello! Yes, I''m new.', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'es', '¡Buenos días! Sí, soy nuevo.', '¡Buenos días! Sí, soy nueva.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'fr', 'Bonjour ! Oui, je suis nouveau.', 'Bonjour ! Oui, je suis nouvelle.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'de', 'Guten Tag! Ja, ich bin neu.', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'it', 'Buongiorno! Sì, sono nuovo.', 'Buongiorno! Sì, sono nuova.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'pt', 'Bom dia! Sim, sou novo aqui.', 'Bom dia! Sim, sou nova aqui.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'be', 'Добры дзень! Так, я новенькі.', 'Добры дзень! Так, я новенькая.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'tr', 'Merhaba! Evet, yeniyim.', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'zh', '您好！对，我是新来的。', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'zh-Hant', '您好！對，我是新來的。', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'ja', 'こんにちは！はい、越してきたばかりです。', null),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'ar', 'مرحبًا! نعم، أنا جديد هنا.', 'مرحبًا! نعم، أنا جديدة هنا.'),
  ('06629024-bc04-5eba-aa63-5a0efbf7be97', 'hi', 'नमस्ते! जी हाँ, मैं नया हूँ।', 'नमस्ते! जी हाँ, मैं नई हूँ।'),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'pl', 'Może przejdziemy na ty? Jestem Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'ru', 'Может, перейдём на «ты»? Я Томек.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'uk', 'Може, перейдемо на «ти»? Я Томек.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'en', 'Shall we use first names? I''m Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'es', '¿Y si nos tuteamos? Soy Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'fr', 'Et si on se tutoyait ? Moi, c''est Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'de', 'Wollen wir uns duzen? Ich bin Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'it', 'Che ne dice di darci del tu? Io sono Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'pt', 'Podemos tratar-nos por tu? Sou o Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'be', 'Можа, пяройдзем на «ты»? Я Томек.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'tr', '“Sen” diye konuşalım mı? Ben Tomek.', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'zh', '咱们别“您”来“您”去了吧？我叫托梅克。', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'zh-Hant', '我們別「您」來「您」去了吧？我叫托梅克。', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'ja', 'よかったら、タメ口で話しませんか？トメクです。', null),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'ar', 'ما رأي حضرتكَ أن نرفع الكلفة بيننا؟ أنا توميك.', 'ما رأي حضرتكِ أن نرفع الكلفة بيننا؟ أنا توميك.'),
  ('5ed68dde-3dcd-55bf-ac4c-1b592572adb5', 'hi', 'क्यों न हम एक-दूसरे को “तुम” कहें? मैं तोमेक हूँ।', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'pl', 'Jasne! Bardzo mi miło.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'ru', 'Конечно! Очень приятно.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'uk', 'Звісно! Дуже приємно.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'en', 'Sure! Very nice to meet you.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'es', '¡Claro! Encantado.', '¡Claro! Encantada.'),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'fr', 'Bien sûr ! Enchanté.', 'Bien sûr ! Enchantée.'),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'de', 'Klar! Freut mich sehr.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'it', 'Certo! Molto piacere.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'pt', 'Claro! Muito prazer.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'be', 'Канечне! Вельмі прыемна.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'tr', 'Tabii! Çok memnun oldum.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'zh', '好啊！很高兴认识你。', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'zh-Hant', '好啊！很高興認識你。', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'ja', 'もちろん！会えてとてもうれしいよ。', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'ar', 'طبعًا! سُررت جدًا بمعرفتك.', null),
  ('80f4d217-4bbf-511a-a846-86abebf89868', 'hi', 'ज़रूर! मिलकर बहुत ख़ुशी हुई।', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'pl', 'Mnie też! Jakby co, mieszkam obok.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'ru', 'Мне тоже! Если что, я живу рядом.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'uk', 'Мені теж! Якщо що, я живу поруч.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'en', 'Me too! If you need anything, I live next door.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'es', '¡Igualmente! Si necesitas algo, vivo al lado.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'fr', 'Moi aussi ! Si besoin, j''habite à côté.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'de', 'Mich auch! Wenn was ist: Ich wohne nebenan.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'it', 'Anche per me! Se ti serve qualcosa, abito qui accanto.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'pt', 'Igualmente! Se precisares de alguma coisa, moro aqui ao lado.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'be', 'Мне таксама! Калі што, я жыву побач.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'tr', 'Ben de! Bir şey olursa hemen yanda oturuyorum.', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'zh', '我也是！有什么事就来找我，我就住隔壁。', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'zh-Hant', '我也是！有什麼事就來找我，我就住隔壁。', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'ja', 'こっちこそ！何かあったら、隣に住んでるからね。', null),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'ar', 'وأنا كذلك! إن احتجتَ شيئًا، فأنا أسكن في الجوار.', 'وأنا كذلك! إن احتجتِ شيئًا، فأنا أسكن في الجوار.'),
  ('c93042ba-6ab3-553d-90a2-9fb9cb55145b', 'hi', 'मुझे भी! कोई ज़रूरत हो, तो मैं बगल में रहता हूँ।', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'pl', 'Dzięki, Tomek! Na razie!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'ru', 'Спасибо, Томек! Пока!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'uk', 'Дякую, Томеку! Бувай!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'en', 'Thanks, Tomek! See you!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'es', '¡Gracias, Tomek! ¡Hasta luego!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'fr', 'Merci, Tomek ! À plus !', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'de', 'Danke, Tomek! Bis dann!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'it', 'Grazie, Tomek! A dopo!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'pt', 'Obrigado, Tomek! Até logo!', 'Obrigada, Tomek! Até logo!'),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'be', 'Дзякуй, Томек! Пакуль!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'tr', 'Sağ ol, Tomek! Görüşürüz!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'zh', '谢啦，托梅克！回头见！', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'zh-Hant', '謝啦，托梅克！回頭見！', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'ja', 'ありがとう、トメク！またね！', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'ar', 'شكرًا يا توميك! أراك لاحقًا!', null),
  ('02893e4f-eb39-5d29-8016-b118685f27dc', 'hi', 'थैंक्स, तोमेक! फिर मिलते हैं!', null),
