  ('65c393a8-9cc1-514e-b17f-298fbf0d816b', 'zh', '邻居', null),
  ('65c393a8-9cc1-514e-b17f-298fbf0d816b', 'zh-Hant', '鄰居', null),
  ('65c393a8-9cc1-514e-b17f-298fbf0d816b', 'ja', '隣人、お隣さん', null),
  ('65c393a8-9cc1-514e-b17f-298fbf0d816b', 'ar', 'جار', 'جارة'),
  ('65c393a8-9cc1-514e-b17f-298fbf0d816b', 'hi', 'पड़ोसी', 'पड़ोसन'),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'pl', 'na ty', null),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'ru', 'на «ты»', null),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'uk', 'на «ти»', null),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'en', 'on first-name terms', null),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'es', 'de tú', null),
  ('8918ae99-933a-57be-b629-70ef795fc9d8', 'fr', 'se tutoyer', null),
