  ('6b07c348-01a0-5f81-8253-54a42012ef2e', 'zh', '当然，好啊', null),
  ('6b07c348-01a0-5f81-8253-54a42012ef2e', 'zh-Hant', '當然，好啊', null),
  ('6b07c348-01a0-5f81-8253-54a42012ef2e', 'ja', 'もちろん', null),
  ('6b07c348-01a0-5f81-8253-54a42012ef2e', 'ar', 'طبعًا', null),
  ('6b07c348-01a0-5f81-8253-54a42012ef2e', 'hi', 'ज़रूर', null),
  ('a126b9dd-5ebc-5841-9968-f4a7ebb98933', 'pl', 'bardzo', null),
  ('a126b9dd-5ebc-5841-9968-f4a7ebb98933', 'ru', 'очень', null),
  ('a126b9dd-5ebc-5841-9968-f4a7ebb98933', 'uk', 'дуже', null),
