  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'de', 'Bitte jemanden, etwas zu wiederholen', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'it', 'Chiedi di ripetere', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'pt', 'Pede para repetirem', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'be', 'Папрасіць паўтарыць', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'tr', 'Birinden tekrar etmesini iste', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'zh', '请对方再说一遍', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'zh-Hant', '請對方再說一次', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'ja', 'もう一度言ってもらおう', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'ar', 'طلب إعادة الكلام', null),
  ('fcd4d44e-4592-521c-8e00-9c50c8bdcf84', 'hi', 'किसी से दोबारा कहने को कहें', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'ru', '«Я» обычно не говорят — глагол уже показывает, кто действует: Rozumiem, а не Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'uk', '«Я» зазвичай не кажуть — дієслово вже показує, хто діє: Rozumiem, а не Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'en', 'Poles usually drop “I” — the verb already shows who: Rozumiem, not Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'es', 'Los polacos suelen omitir el «yo»: el verbo ya indica quién es. Rozumiem, no Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'fr', 'En polonais, on omet généralement « je » — le verbe montre déjà qui parle : Rozumiem, et non Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'de', 'Polen lassen „ich“ meist weg – das Verb zeigt schon, wer gemeint ist: Rozumiem, nicht Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'it', 'Come in italiano, in polacco di solito non si dice «io»: il verbo mostra già chi parla. Rozumiem, non Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'pt', 'Os polacos costumam omitir o «eu» — o verbo já mostra quem é: Rozumiem, e não Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'be', '«Я» звычайна не кажуць — дзеяслоў ужо паказвае, хто робіць дзеянне: Rozumiem, а не Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'tr', 'Polonyalılar genelde “ben” demez, fiil kimin yaptığını zaten gösterir: Rozumiem, Ja rozumiem değil.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'zh', '波兰人通常省略“我”——动词本身就表明了是谁：说 Rozumiem，而不是 Ja rozumiem。', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'zh-Hant', '波蘭人通常會省略「我」——動詞本身就看得出是誰：說 Rozumiem，不說 Ja rozumiem。', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'ja', 'ポーランド人はふつう「私」を省きます。動詞の形でだれのことかわかるからです：Ja rozumiem ではなく Rozumiem。', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'ar', 'عادةً ما يحذف البولنديون «أنا»، فالفعل نفسه يدل على الفاعل: Rozumiem، وليس Ja rozumiem.', null),
  ('1cc5c318-375d-5d66-90a7-c346745f4037', 'hi', 'पोलिश लोग आम तौर पर “मैं” नहीं बोलते — क्रिया से ही पता चल जाता है कि कौन: Rozumiem, न कि Ja rozumiem।', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'pl', 'Proszę wypełnić ten formularz.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'ru', 'Заполните, пожалуйста, эту форму.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'uk', 'Заповніть, будь ласка, цю форму.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'en', 'Please fill in this form.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'es', 'Rellene este formulario, por favor.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'fr', 'Remplissez ce formulaire, s''il vous plaît.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'de', 'Bitte füllen Sie dieses Formular aus.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'it', 'Compili questo modulo, per favore.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'pt', 'Preencha este formulário, por favor.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'be', 'Запоўніце, калі ласка, гэты бланк.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'tr', 'Lütfen bu formu doldurun.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'zh', '请填一下这张表。', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'zh-Hant', '請填寫這張表格。', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'ja', 'この用紙にご記入ください。', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'ar', 'يُرجى ملء هذه الاستمارة.', null),
  ('97638ba2-d0d9-5d2c-926a-a90ae0af97e4', 'hi', 'कृपया यह फ़ॉर्म भर दीजिए।', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'pl', 'Przepraszam, nie rozumiem.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'ru', 'Извините, я не понимаю.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'uk', 'Перепрошую, я не розумію.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'en', 'Sorry, I don''t understand.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'es', 'Disculpe, no entiendo.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'fr', 'Pardon, je ne comprends pas.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'de', 'Entschuldigung, ich verstehe nicht.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'it', 'Mi scusi, non capisco.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'pt', 'Desculpe, não percebo.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'be', 'Прабачце, я не разумею.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'tr', 'Affedersiniz, anlamıyorum.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'zh', '不好意思，我听不懂。', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'zh-Hant', '不好意思，我聽不懂。', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'ja', 'すみません、わかりません。', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'ar', 'عذرًا، لا أفهم.', null),
  ('9d61573d-92e8-598f-ab26-dfe15bc38a88', 'hi', 'माफ़ कीजिए, मुझे समझ नहीं आया।', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'pl', 'Formularz trzeba wypełnić i podpisać.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'ru', 'Форму нужно заполнить и подписать.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'uk', 'Форму треба заповнити й підписати.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'en', 'The form needs to be filled in and signed.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'es', 'Hay que rellenar el formulario y firmarlo.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'fr', 'Il faut remplir et signer le formulaire.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'de', 'Das Formular muss ausgefüllt und unterschrieben werden.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'it', 'Il modulo va compilato e firmato.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'pt', 'É preciso preencher e assinar o formulário.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'be', 'Бланк трэба запоўніць і падпісаць.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'tr', 'Formun doldurulup imzalanması gerekiyor.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'zh', '这张表需要填好并签字。', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'zh-Hant', '這張表格要填好並簽名。', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'ja', '用紙に記入して、署名する必要があります。', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'ar', 'يجب ملء الاستمارة وتوقيعها.', null),
  ('3fcfad48-e89a-5f30-b8a8-3ffff7e2275a', 'hi', 'फ़ॉर्म भरकर उस पर साइन करना होगा।', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'pl', 'Może pani powtórzyć wolniej?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'ru', 'Можете повторить помедленнее?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'uk', 'Можете повторити повільніше?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'en', 'Could you say it again more slowly?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'es', '¿Puede repetirlo más despacio?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'fr', 'Vous pouvez répéter plus lentement ?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'de', 'Können Sie das langsamer wiederholen?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'it', 'Può ripetere più lentamente?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'pt', 'A senhora pode repetir mais devagar?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'be', 'Вы можаце паўтарыць павольней?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'tr', 'Daha yavaş tekrar edebilir misiniz?', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'zh', '您能说慢一点，再说一遍吗？', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'zh-Hant', '您可以說慢一點，再說一次嗎？', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'ja', 'もう少しゆっくり、もう一度言っていただけますか？', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'ar', 'هل يمكن لحضرتكِ أن تعيدي ذلك ببطء أكثر؟', null),
  ('5a5da34c-4bc7-56ed-a1a0-71ed18293365', 'hi', 'क्या आप थोड़ा धीरे दोहरा सकती हैं?', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'pl', 'Oczywiście. Proszę wypełnić formularz i podpisać tutaj.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'ru', 'Конечно. Заполните форму и подпишите здесь.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'uk', 'Звісно. Заповніть форму й підпишіть тут.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'en', 'Of course. Please fill in the form and sign here.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'es', 'Por supuesto. Rellene el formulario y firme aquí, por favor.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'fr', 'Bien sûr. Remplissez le formulaire et signez ici, s''il vous plaît.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'de', 'Natürlich. Bitte füllen Sie das Formular aus und unterschreiben Sie hier.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'it', 'Certo. Compili il modulo e firmi qui, per favore.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'pt', 'Com certeza. Preencha o formulário e assine aqui, por favor.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'be', 'Вядома. Запоўніце бланк і падпішыце тут.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'tr', 'Tabii. Lütfen formu doldurun ve buraya imza atın.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'zh', '当然。请填好表格，然后在这里签字。', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'zh-Hant', '當然。請填好表格，然後在這裡簽名。', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'ja', 'もちろんです。用紙にご記入のうえ、こちらに署名してください。', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'ar', 'بالطبع. يُرجى ملء الاستمارة والتوقيع هنا.', null),
  ('b970ee81-5440-5e30-90c4-620db921daa2', 'hi', 'बिल्कुल। कृपया फ़ॉर्म भरिए और यहाँ साइन कीजिए।', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'pl', 'Aha, teraz rozumiem! Dziękuję.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'ru', 'А, теперь понимаю! Спасибо.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'uk', 'А, тепер розумію! Дякую.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'en', 'Ah, now I understand! Thank you.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'es', '¡Ah, ahora lo entiendo! Gracias.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'fr', 'Ah, maintenant je comprends ! Merci.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'de', 'Ach so, jetzt verstehe ich! Danke.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'it', 'Ah, adesso ho capito! Grazie.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'pt', 'Ah, agora percebo! Obrigado.', 'Ah, agora percebo! Obrigada.'),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'be', 'А, цяпер разумею! Дзякуй.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'tr', 'Haa, şimdi anladım! Teşekkür ederim.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'zh', '哦，现在我明白了！谢谢您。', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'zh-Hant', '喔，現在我懂了！謝謝您。', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'ja', 'ああ、今わかりました！ありがとうございます。', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'ar', 'آه، الآن فهمت! شكرًا.', null),
  ('28d2e886-2763-5900-b4bb-02d47e0f4e8f', 'hi', 'अच्छा, अब समझ आया! शुक्रिया।', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'pl', 'formularz', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'ru', 'форма, бланк', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'uk', 'форма, бланк', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'en', 'form', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'es', 'formulario', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'fr', 'formulaire', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'de', 'Formular', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'it', 'modulo', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'pt', 'formulário', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'be', 'бланк, форма', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'tr', 'form', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'zh', '表格', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'zh-Hant', '表格', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'ja', '用紙、申込書', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'ar', 'استمارة', null),
  ('c10f6a65-c9a0-5613-9409-e73a74efdb17', 'hi', 'फ़ॉर्म', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'pl', 'rozumiem', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'ru', 'понимаю', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'uk', 'розумію', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'en', 'I understand', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'es', 'entiendo', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'fr', 'je comprends', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'de', 'ich verstehe', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'it', 'capisco', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'pt', 'percebo', null),
  ('84c4c069-ce78-5e8e-a523-9549e8fb7af7', 'be', 'разумею', null),
