  ('39849189-a204-5558-8900-053767ddc6c3', 'hi', 'अंग्रेज़ी में', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'pl', 'Proszę mówić po angielsku.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'ru', 'Говорите по-английски, пожалуйста.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'uk', 'Говоріть англійською, будь ласка.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'en', 'Please speak English.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'es', 'Hable en inglés, por favor.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'fr', 'Parlez en anglais, s''il vous plaît.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'de', 'Bitte sprechen Sie Englisch.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'it', 'Parli in inglese, per favore.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'pt', 'Fale em inglês, por favor.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'be', 'Гаварыце па-англійску, калі ласка.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'tr', 'Lütfen İngilizce konuşun.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'zh', '请说英语。', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'zh-Hant', '請說英文。', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'ja', '英語で話してください。', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'ar', 'يُرجى التحدث بالإنجليزية.', null),
  ('e84aa552-4e16-563f-9d74-d2b1978096c6', 'hi', 'कृपया अंग्रेज़ी में बोलिए।', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'pl', 'Pan i pani', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'ru', 'Вежливое «вы»', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'uk', 'Ввічливе «ви»', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'en', 'Sir and madam', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'es', 'Señor y señora', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'fr', 'Monsieur et madame', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'de', 'Höflich per Sie', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'it', 'Signore e signora', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'pt', 'O senhor e a senhora', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'be', 'Ветлівае «вы»', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'tr', 'Beyefendi ve hanımefendi', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'zh', '先生和女士', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'zh-Hant', '先生與女士', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'ja', 'ていねいな呼びかけ', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'ar', 'سيدي وسيدتي', null),
  ('becf8547-b8e3-5a86-b128-0cb4881f2270', 'hi', 'आदर से “आप”', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'pl', 'Rozmawiaj grzecznie z nieznajomym', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'ru', 'Вежливо говорить с незнакомыми', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'uk', 'Ввічливо говорити з незнайомими', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'en', 'Talk politely to strangers', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'es', 'Habla con educación a un desconocido', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'fr', 'Parle poliment à un inconnu', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'de', 'Sprich höflich mit Fremden', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'it', 'Parla con gentilezza a uno sconosciuto', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'pt', 'Fala com educação com um desconhecido', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'be', 'Ветліва размаўляць з незнаёмымі', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'tr', 'Yabancılarla kibarca konuş', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'zh', '礼貌地和陌生人说话', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'zh-Hant', '有禮貌地跟陌生人說話', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'ja', '知らない人とていねいに話そう', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'ar', 'التحدث بأدب مع الغرباء', null),
  ('20cc1613-21d6-58ff-a243-603b6a455214', 'hi', 'अजनबियों से शिष्टता से बात करें', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'ru', 'К незнакомым обращаются pan (к мужчине), pani (к женщине), państwo (к группе). Глагол — как с «он/она»: Czy ma pan…? С большой буквы Pan пишут только в письмах.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'uk', 'До незнайомих звертаються pan (до чоловіка), pani (до жінки), państwo (до групи). Дієслово — як з «він/вона»: Czy ma pan…? З великої літери Pan пишуть лише в листах.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'en', 'Strangers are addressed as pan (a man), pani (a woman), państwo (a group). The verb is the “he/she” form: Czy ma pan…? Capital “Pan” is only for letters.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'es', 'A los desconocidos se les habla de pan (a un hombre), pani (a una mujer) o państwo (a un grupo). El verbo va en tercera persona, como con usted: Czy ma pan…? Pan con mayúscula solo se escribe en cartas.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'fr', 'On s''adresse à un inconnu avec pan (à un homme), pani (à une femme), państwo (à un groupe). Le verbe se met à la forme « il/elle » : Czy ma pan…? Pan avec une majuscule, c''est seulement dans les lettres.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'de', 'Fremde spricht man mit pan (einen Mann), pani (eine Frau) und państwo (eine Gruppe) an. Das Verb steht in der „er/sie“-Form: Czy ma pan…? Großes „Pan“ schreibt man nur in Briefen.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'it', 'Agli sconosciuti ci si rivolge con pan (a un uomo), pani (a una donna), państwo (a un gruppo). Il verbo va alla terza persona, come con il Lei: Czy ma pan…? Pan con la maiuscola si scrive solo nelle lettere.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'pt', 'Aos desconhecidos trata-se por pan (a um homem), pani (a uma mulher) ou państwo (a um grupo). O verbo vai na terceira pessoa, como com «o senhor»: Czy ma pan…? Pan com maiúscula só se escreve em cartas.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'be', 'Да незнаёмых звяртаюцца pan (да мужчыны), pani (да жанчыны), państwo (да групы). Дзеяслоў — як з «ён/яна»: Czy ma pan…? З вялікай літары Pan пішуць толькі ў лістах.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'tr', 'Yabancılara pan (erkeğe), pani (kadına), państwo (gruba) diye hitap edilir. Fiil “o” biçiminde olur: Czy ma pan…? Büyük harfli “Pan” yalnızca mektuplarda yazılır.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'zh', '称呼陌生人用 pan（男士）、pani（女士）、państwo（一群人）。动词用“他/她”的形式：Czy ma pan…? 大写的“Pan”只用在书信里。', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'zh-Hant', '稱呼陌生人用 pan（男士）、pani（女士）、państwo（一群人）。動詞要用「他／她」的形式：Czy ma pan…? 大寫的「Pan」只用在書信裡。', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'ja', '知らない人には pan（男性）、pani（女性）、państwo（グループ）と呼びかけます。動詞は「彼・彼女」の形を使います：Czy ma pan…? 大文字の Pan は手紙の中だけです。', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'ar', 'يُخاطَب الغرباء بـ pan (للرجل)، و pani (للمرأة)، و państwo (لمجموعة). ويأتي الفعل بصيغة «هو/هي»: Czy ma pan…? أما Pan بالحرف الكبير فلا يُكتب إلا في الرسائل.', null),
  ('3a8e4841-8476-52b6-8052-762ae4208ce0', 'hi', 'अजनबियों को pan (पुरुष), pani (महिला), państwo (समूह) कहकर संबोधित करते हैं। क्रिया “वह” वाले रूप में होती है: Czy ma pan…? बड़े अक्षर वाला Pan सिर्फ़ चिट्ठियों में लिखा जाता है।', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'pl', 'Dzień dobry! Co dla pana?', 'Dzień dobry! Co dla pani?'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'ru', 'Здравствуйте! Что для вас?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'uk', 'Добрий день! Що для вас?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'en', 'Hello! What can I get you?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'es', '¡Buenos días! ¿Qué desea?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'fr', 'Bonjour monsieur ! Que désirez-vous ?', 'Bonjour madame ! Que désirez-vous ?'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'de', 'Guten Tag! Was darf es sein?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'it', 'Buongiorno! Cosa desidera il signore?', 'Buongiorno! Cosa desidera la signora?'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'pt', 'Bom dia! O que deseja o senhor?', 'Bom dia! O que deseja a senhora?'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'be', 'Добры дзень! Што вам прапанаваць?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'tr', 'Merhaba! Size ne verelim?', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'zh', '您好！先生，您需要点什么？', '您好！女士，您需要点什么？'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'zh-Hant', '您好！先生，您需要什麼？', '您好！小姐，您需要什麼？'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'ja', 'こんにちは！何にいたしましょうか？', null),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'ar', 'مرحبًا! ماذا أقدّم لحضرتكَ؟', 'مرحبًا! ماذا أقدّم لحضرتكِ؟'),
  ('a7b3a161-191f-5dae-ab8f-23cac00cc6f0', 'hi', 'नमस्ते! आपको क्या चाहिए?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'pl', 'Dzień dobry! Czy ma pan mapę miasta?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'ru', 'Здравствуйте! У вас есть карта города?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'uk', 'Добрий день! У вас є мапа міста?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'en', 'Hello! Do you have a city map?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'es', '¡Buenos días! ¿Tiene usted un mapa de la ciudad?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'fr', 'Bonjour ! Vous avez un plan de la ville ?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'de', 'Guten Tag! Haben Sie einen Stadtplan?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'it', 'Buongiorno! Ha una mappa della città?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'pt', 'Bom dia! O senhor tem um mapa da cidade?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'be', 'Добры дзень! У вас ёсць карта горада?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'tr', 'Merhaba! Şehir haritanız var mı?', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'zh', '您好！您这儿有城市地图吗？', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'zh-Hant', '您好！請問您這裡有城市地圖嗎？', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'ja', 'こんにちは！街の地図はありますか？', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'ar', 'مرحبًا! هل لدى حضرتك خريطة للمدينة؟', null),
  ('63ff2f67-4e7c-5c64-87b3-9011dbcc5d1a', 'hi', 'नमस्ते! क्या आपके पास शहर का नक़्शा है?', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'pl', 'Tak, proszę. Czy pan jest turystą?', 'Tak, proszę. Czy pani jest turystką?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'ru', 'Да, пожалуйста. Вы турист?', 'Да, пожалуйста. Вы туристка?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'uk', 'Так, прошу. Ви турист?', 'Так, прошу. Ви туристка?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'en', 'Yes, here you go. Are you a tourist?', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'es', 'Sí, aquí tiene. ¿Es usted turista?', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'fr', 'Oui, tenez. Vous êtes touriste ?', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'de', 'Ja, bitte schön. Sind Sie Tourist?', 'Ja, bitte schön. Sind Sie Touristin?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'it', 'Sì, ecco. Lei è un turista?', 'Sì, ecco. Lei è una turista?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'pt', 'Sim, aqui tem. O senhor é turista?', 'Sim, aqui tem. A senhora é turista?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'be', 'Так, калі ласка. Вы турыст?', 'Так, калі ласка. Вы турыстка?'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'tr', 'Evet, buyurun. Turist misiniz?', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'zh', '有，给您。您是来旅游的吗？', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'zh-Hant', '有的，給您。您是來觀光的嗎？', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'ja', 'はい、どうぞ。観光の方ですか？', null),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'ar', 'نعم، تفضّل. هل حضرتكَ سائح؟', 'نعم، تفضّلي. هل حضرتكِ سائحة؟'),
  ('6a934c4b-12c4-5e35-ab5e-37a8e90af54e', 'hi', 'जी हाँ, यह लीजिए। क्या आप टूरिस्ट हैं?', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'pl', 'Nie, mieszkam tutaj.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'ru', 'Нет, я живу здесь.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'uk', 'Ні, я живу тут.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'en', 'No, I live here.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'es', 'No, vivo aquí.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'fr', 'Non, j''habite ici.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'de', 'Nein, ich wohne hier.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'it', 'No, abito qui.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'pt', 'Não, moro aqui.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'be', 'Не, я жыву тут.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'tr', 'Hayır, burada yaşıyorum.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'zh', '不是，我住在这儿。', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'zh-Hant', '不是，我住在這裡。', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'ja', 'いいえ、ここに住んでいます。', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'ar', 'لا، أسكن هنا.', null),
  ('9480ad85-381b-5686-a7eb-30c70c26d0cf', 'hi', 'नहीं, मैं यहीं रहता हूँ।', 'नहीं, मैं यहीं रहती हूँ।'),
  ('95e09d11-6dc5-50de-b145-745a403892e4', 'pl', 'To witamy w Warszawie!', null),
  ('95e09d11-6dc5-50de-b145-745a403892e4', 'ru', 'Тогда добро пожаловать в Варшаву!', null),
  ('95e09d11-6dc5-50de-b145-745a403892e4', 'uk', 'Тоді ласкаво просимо до Варшави!', null),
  ('95e09d11-6dc5-50de-b145-745a403892e4', 'en', 'Then welcome to Warsaw!', null),
  ('95e09d11-6dc5-50de-b145-745a403892e4', 'es', '¡Pues bienvenido a Varsovia!', '¡Pues bienvenida a Varsovia!'),
