  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'ru', 'С pan / pani глагол как с «он»: ma, a не masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'uk', 'З pan / pani дієслово як з «він»: ma, а не masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'en', 'With pan / pani use the “he” form: ma, not masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'es', 'Con pan / pani se usa la forma de «él»: ma, no masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'fr', 'Avec pan / pani, on utilise la forme « il » : ma, et non masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'de', 'Mit pan / pani steht das Verb in der „er“-Form: ma, nicht masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'it', 'Con pan / pani si usa la forma «lui»: ma, non masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'pt', 'Com pan / pani usa-se a forma de «ele»: ma, e não masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'be', 'З pan / pani дзеяслоў як з «ён»: ma, а не masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'tr', 'pan / pani ile fiil “o” biçiminde kullanılır: ma, masz değil.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'zh', '和 pan / pani 搭配时用“他”的形式：ma，而不是 masz。', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'zh-Hant', '搭配 pan / pani 時要用「他」的形式：說 ma，不說 masz。', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'ja', 'pan / pani には「彼」の形を使います：masz ではなく ma。', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'ar', 'مع pan / pani يأتي الفعل بصيغة «هو»: ma، وليس masz.', null),
  ('24449ad6-69a0-5c09-b98e-265c950589e1', 'hi', 'pan / pani के साथ “वह” वाला रूप लगाएँ: ma, न कि masz।', null),
