  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'ru', 'Вопрос, на который отвечают «да» или «нет», часто начинается с czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'uk', 'Питання, на яке відповідають «так» або «ні», часто починається з czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'en', 'Yes/no questions often start with czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'es', 'Las preguntas de sí o no suelen empezar con czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'fr', 'Les questions auxquelles on répond par « oui » ou « non » commencent souvent par czy : Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'de', 'Ja-Nein-Fragen beginnen oft mit czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'it', 'Le domande a cui si risponde «sì» o «no» iniziano spesso con czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'pt', 'As perguntas de sim ou não começam muitas vezes com czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'be', 'Пытанне, на якое адказваюць «так» ці «не», часта пачынаецца з czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'tr', 'Evet/hayır soruları genellikle czy ile başlar: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'zh', '一般疑问句（用“是”或“不是”回答的问题）常以 czy 开头：Czy mówi pan po angielsku?', null),
