  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'ja', '「はい／いいえ」で答える質問は、よく czy で始まります：Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'ar', 'كثيرًا ما تبدأ الأسئلة التي جوابها «نعم» أو «لا» بـ czy: Czy mówi pan po angielsku?', null),
  ('228fd366-cc7b-59e7-a9a6-2a721ff2cefd', 'hi', 'जिन सवालों का जवाब “हाँ” या “नहीं” में होता है, वे अक्सर czy से शुरू होते हैं: Czy mówi pan po angielsku?', null),
