  ('1b88696f-07e5-595b-8ed6-6629fbe1c8bc', 'zh', '打扰一下，您会说英语吗？', null),
  ('1b88696f-07e5-595b-8ed6-6629fbe1c8bc', 'zh-Hant', '不好意思，請問您會說英文嗎？', null),
  ('1b88696f-07e5-595b-8ed6-6629fbe1c8bc', 'ja', 'すみません、英語は話せますか？', null),
  ('1b88696f-07e5-595b-8ed6-6629fbe1c8bc', 'ar', 'عذرًا، هل حضرتك تتكلم الإنجليزية؟', null),
  ('1b88696f-07e5-595b-8ed6-6629fbe1c8bc', 'hi', 'माफ़ कीजिए, क्या आप अंग्रेज़ी बोलते हैं?', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'pl', 'Niestety nie, tylko po polsku.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'ru', 'К сожалению, нет, только по-польски.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'uk', 'На жаль, ні, тільки польською.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'en', 'Sorry, no, only Polish.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'es', 'Por desgracia no, solo polaco.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'fr', 'Malheureusement non, seulement polonais.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'de', 'Leider nicht, nur Polnisch.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'it', 'Purtroppo no, solo polacco.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'pt', 'Infelizmente não, só polaco.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'be', 'На жаль, не, толькі па-польску.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'tr', 'Maalesef hayır, sadece Lehçe.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'zh', '可惜不会，我只会说波兰语。', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'zh-Hant', '可惜不會，我只會說波蘭語。', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'ja', '残念ながら話せません。ポーランド語だけです。', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'ar', 'للأسف لا، البولندية فقط.', null),
  ('f881b63a-8320-59f9-8b9d-f17b3bfa6869', 'hi', 'अफ़सोस, नहीं, सिर्फ़ पोलिश।', null),
  ('37f04c1f-05d2-5b8a-bef7-b3fe435321b8', 'pl', 'Mówię trochę po polsku.', null),
