  ('37f04c1f-05d2-5b8a-bef7-b3fe435321b8', 'ja', 'ポーランド語が少し話せます。', null),
  ('37f04c1f-05d2-5b8a-bef7-b3fe435321b8', 'ar', 'أتكلم البولندية قليلًا.', null),
  ('37f04c1f-05d2-5b8a-bef7-b3fe435321b8', 'hi', 'मैं थोड़ी-सी पोलिश बोलता हूँ।', 'मैं थोड़ी-सी पोलिश बोलती हूँ।'),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'pl', 'Bardzo dobrze pan mówi! A czego pan szuka?', 'Bardzo dobrze pani mówi! A czego pani szuka?'),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'ru', 'Вы очень хорошо говорите! А что вы ищете?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'uk', 'Ви дуже добре говорите! А що ви шукаєте?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'en', 'You speak very well! So what are you looking for?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'es', '¡Habla usted muy bien! ¿Y qué busca?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'fr', 'Vous parlez très bien ! Alors, que cherchez-vous ?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'de', 'Sie sprechen sehr gut! Und was suchen Sie?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'it', 'Parla molto bene! E cosa cerca?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'pt', 'O senhor fala muito bem! E o que procura?', 'A senhora fala muito bem! E o que procura?'),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'be', 'Вы вельмі добра гаворыце! А што вы шукаеце?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'tr', 'Çok iyi konuşuyorsunuz! Peki ne arıyorsunuz?', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'zh', '您说得很好！那您在找什么？', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'zh-Hant', '您說得很好！那您在找什麼呢？', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'ja', 'とてもお上手ですね！それで、何をお探しですか？', null),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'ar', 'حضرتكَ تتكلم جيدًا جدًا! وعمّ تبحث؟', 'حضرتكِ تتكلمين جيدًا جدًا! وعمّ تبحثين؟'),
  ('9604ec2a-c446-5c11-844e-3e63b061b5df', 'hi', 'आप तो बहुत अच्छा बोलते हैं! तो आप क्या ढूँढ रहे हैं?', 'आप तो बहुत अच्छा बोलती हैं! तो आप क्या ढूँढ रही हैं?'),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'pl', 'Czy może pan mówić wolniej?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'ru', 'Вы можете говорить медленнее?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'uk', 'Ви можете говорити повільніше?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'en', 'Could you speak more slowly?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'es', '¿Puede hablar más despacio?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'fr', 'Vous pouvez parler plus lentement ?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'de', 'Können Sie langsamer sprechen?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'it', 'Può parlare più lentamente?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'pt', 'O senhor pode falar mais devagar?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'be', 'Вы можаце гаварыць павольней?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'tr', 'Daha yavaş konuşabilir misiniz?', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'zh', '您能说慢一点吗？', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'zh-Hant', '您可以說慢一點嗎？', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'ja', 'もう少しゆっくり話していただけますか？', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'ar', 'هل يمكن لحضرتك أن تتكلم ببطء أكثر؟', null),
  ('37ce697c-4f6f-54c9-8445-45dcba5e125e', 'hi', 'क्या आप थोड़ा धीरे बोल सकते हैं?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'pl', 'Oczywiście. Czego pan szuka?', 'Oczywiście. Czego pani szuka?'),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'ru', 'Конечно. Что вы ищете?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'uk', 'Звісно. Що ви шукаєте?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'en', 'Of course. What are you looking for?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'es', 'Claro. ¿Qué busca?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'fr', 'Bien sûr. Que cherchez-vous ?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'de', 'Natürlich. Was suchen Sie?', null),
