  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'be', 'Вядома. Што вы шукаеце?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'tr', 'Tabii. Ne arıyorsunuz?', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'zh', '当然。您在找什么？', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'zh-Hant', '當然。您在找什麼？', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'ja', 'もちろんです。何をお探しですか？', null),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'ar', 'بالطبع. عمّ تبحث حضرتكَ؟', 'بالطبع. عمّ تبحثين حضرتكِ؟'),
  ('41696434-d5f1-58c0-939c-6b9ea3ab7c40', 'hi', 'बिल्कुल। आप क्या ढूँढ रहे हैं?', 'बिल्कुल। आप क्या ढूँढ रही हैं?'),
