  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'ru', 'Слова меняют окончания: woda → Poproszę wodę. Учи фразу целиком — так быстрее, чем учить правила.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'uk', 'Слова змінюють закінчення: woda → Poproszę wodę. Вчи фразу цілком — так швидше, ніж учити правила.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'en', 'Words change their endings: woda → Poproszę wodę. Learn the whole phrase — it''s faster than rules.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'es', 'Las palabras cambian de terminación: woda → Poproszę wodę. Aprende la frase entera: es más rápido que las reglas.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'fr', 'Les mots changent de terminaison : woda → Poproszę wodę. Apprends l''expression entière — c''est plus rapide que les règles.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'de', 'Wörter ändern ihre Endung: woda → Poproszę wodę. Lern den ganzen Ausdruck – das geht schneller als Regeln.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'it', 'Le parole cambiano desinenza: woda → Poproszę wodę. Impara la frase intera: è più veloce che studiare le regole.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'pt', 'As palavras mudam de terminação: woda → Poproszę wodę. Aprende a frase inteira — é mais rápido do que as regras.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'be', 'Словы мяняюць канчаткі: woda → Poproszę wodę. Вучы фразу цалкам — так хутчэй, чым вучыць правілы.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'tr', 'Kelimelerin sonu değişir: woda → Poproszę wodę. İfadenin tamamını öğren, kural ezberlemekten daha hızlı.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'zh', '词尾会变：woda → Poproszę wodę。把整句话记下来——比背规则快。', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'zh-Hant', '字尾會變化：woda → Poproszę wodę。直接記整句話——比背規則快。', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'ja', '単語は語尾が変わります：woda → Poproszę wodę。ルールを覚えるより、フレーズごと覚えるほうが早いです。', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'ar', 'تتغير نهايات الكلمات: woda → Poproszę wodę. حفظ العبارة كاملة أسرع من حفظ القواعد.', null),
  ('8cbae39a-9a74-5a3b-bf1e-0619f9c9ad9a', 'hi', 'शब्दों के अंत बदलते हैं: woda → Poproszę wodę। पूरा वाक्यांश याद करें — यह नियम रटने से ज़्यादा तेज़ है।', null),
