  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'ru', 'После «poproszę» woda → wodę, kawa → kawę: у слов на -a окончание -ę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'uk', 'Після «poproszę» woda → wodę, kawa → kawę: у слів на -a закінчення -ę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'en', 'After “poproszę”, words ending in -a take -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'es', 'Después de «poproszę», las palabras en -a cambian a -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'fr', 'Après « poproszę », les mots en -a prennent -ę : woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'de', 'Nach „poproszę“ bekommen Wörter auf -a die Endung -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'it', 'Dopo «poproszę» le parole in -a prendono -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'pt', 'Depois de «poproszę», as palavras em -a passam a -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'be', 'Пасля «poproszę» словы на -a атрымліваюць канчатак -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'tr', '“poproszę” kelimesinden sonra -a ile biten kelimeler -ę alır: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'zh', '在“poproszę”后面，以 -a 结尾的词要变成 -ę：woda → wodę，kawa → kawę。', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'zh-Hant', '在「poproszę」後面，-a 結尾的字要變成 -ę：woda → wodę，kawa → kawę。', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'ja', '「poproszę」のあとでは、-a で終わる単語は -ę になります：woda → wodę, kawa → kawę。', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'ar', 'بعد «poproszę» تصبح نهاية الكلمات المنتهية بـ -a هي -ę: woda → wodę, kawa → kawę.', null),
  ('1169eb2c-6694-5150-9b11-c1adf8e8958b', 'hi', '“poproszę” के बाद -a पर ख़त्म होने वाले शब्द -ę लेते हैं: woda → wodę, kawa → kawę।', null),
