  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'pl', 'Powiedz, jak masz na imię i gdzie mieszkasz', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'ru', 'Сказать, как тебя зовут и где ты живёшь', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'uk', 'Сказати, як тебе звати і де ти живеш', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'en', 'Say your name and where you live', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'es', 'Di cómo te llamas y dónde vives', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'fr', 'Dis comment tu t''appelles et où tu habites', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'de', 'Sag, wie du heißt und wo du wohnst', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'it', 'Di'' come ti chiami e dove abiti', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'pt', 'Diz como te chamas e onde moras', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'be', 'Сказаць, як цябе завуць і дзе ты жывеш', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'tr', 'Adını ve nerede yaşadığını söyle', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'zh', '说说你叫什么、住在哪里', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'zh-Hant', '說說你叫什麼、住在哪裡', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'ja', '名前と住んでいる場所を言おう', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'ar', 'التعريف باسمي ومكان سكني', null),
  ('8244983b-698c-5cf4-9897-344824d0e5e9', 'hi', 'अपना नाम और रहने की जगह बताएँ', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'ru', 'С ровесником и ребёнком — на «ты»: Jak masz na imię? Со взрослым незнакомым — Jak ma pan / pani na imię? Официально спрашивают фамилию: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'uk', 'З ровесником і дитиною — на «ти»: Jak masz na imię? З дорослим незнайомим — Jak ma pan / pani na imię? Офіційно питають прізвище: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'en', 'With peers and kids use “ty”: Jak masz na imię? With an adult stranger: Jak ma pan / pani na imię? Officially they ask your surname: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'es', 'Con gente de tu edad y con niños se habla de tú (ty): Jak masz na imię? Con un adulto desconocido: Jak ma pan / pani na imię? En trámites oficiales te preguntan el apellido: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'fr', 'Avec quelqu''un de ton âge ou un enfant, on se tutoie : Jak masz na imię? Avec un adulte inconnu : Jak ma pan / pani na imię? Dans un cadre officiel, on demande le nom de famille : Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'de', 'Mit Gleichaltrigen und Kindern sagt man „ty“ (du): Jak masz na imię? Mit einem erwachsenen Fremden: Jak ma pan / pani na imię? Offiziell fragt man nach dem Nachnamen: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'it', 'Con i coetanei e i bambini si dà del tu: Jak masz na imię? Con un adulto sconosciuto: Jak ma pan / pani na imię? In contesti ufficiali ti chiedono il cognome: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'pt', 'Com pessoas da tua idade e com crianças trata-se por tu (ty): Jak masz na imię? Com um adulto desconhecido: Jak ma pan / pani na imię? Em situações oficiais perguntam o apelido: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'be', 'З равеснікам і дзіцём — на «ты»: Jak masz na imię? З дарослым незнаёмым — Jak ma pan / pani na imię? Афіцыйна пытаюць прозвішча: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'tr', 'Yaşıtlarla ve çocuklarla “ty” (sen) kullanılır: Jak masz na imię? Yetişkin bir yabancıyla: Jak ma pan / pani na imię? Resmî ortamda soyadını sorarlar: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'zh', '和同龄人、孩子说话用“ty”：Jak masz na imię? 对成年的陌生人用：Jak ma pan / pani na imię? 正式场合会问你的姓：Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'zh-Hant', '跟同年齡的人、小孩說話用「ty」：Jak masz na imię? 對陌生的成年人用：Jak ma pan / pani na imię? 正式場合會問你的姓：Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'ja', '同年代の人や子どもには「ty」を使います：Jak masz na imię? 知らない大人には：Jak ma pan / pani na imię? 公的な場では名字を聞かれます：Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'ar', 'مع الأقران والأطفال يُستخدم «ty»: Jak masz na imię? ومع شخص بالغ غريب: Jak ma pan / pani na imię? وفي المواقف الرسمية يُسأل عن اسم العائلة: Jak się pan nazywa?', null),
  ('0cd3cbe4-3ee3-5917-acb9-a0ad2ef51d2f', 'hi', 'हमउम्र लोगों और बच्चों से “ty”: Jak masz na imię? किसी अनजान बड़े व्यक्ति से: Jak ma pan / pani na imię? औपचारिक जगहों पर उपनाम पूछा जाता है: Jak się pan nazywa?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'pl', 'Cześć! Jak masz na imię?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'ru', 'Привет! Как тебя зовут?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'uk', 'Привіт! Як тебе звати?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'en', 'Hi! What''s your name?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'es', '¡Hola! ¿Cómo te llamas?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'fr', 'Salut ! Comment tu t''appelles ?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'de', 'Hallo! Wie heißt du?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'it', 'Ciao! Come ti chiami?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'pt', 'Olá! Como te chamas?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'be', 'Прывітанне! Як цябе завуць?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'tr', 'Selam! Adın ne?', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'zh', '嗨！你叫什么名字？', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'zh-Hant', '嗨！你叫什麼名字？', '嗨！妳叫什麼名字？'),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'ja', 'やあ！名前は？', null),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'ar', 'مرحبًا! ما اسمكَ؟', 'مرحبًا! ما اسمكِ؟'),
  ('2e246626-bbc4-54f3-b493-761e752d9d3f', 'hi', 'हाय! तुम्हारा नाम क्या है?', null),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'pl', 'Mam na imię Kuba. A ty?', 'Mam na imię Ola. A ty?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'ru', 'Меня зовут Куба. А тебя?', 'Меня зовут Оля. А тебя?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'uk', 'Мене звати Куба. А тебе?', 'Мене звати Оля. А тебе?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'en', 'My name is Kuba. And you?', 'My name is Ola. And you?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'es', 'Me llamo Kuba. ¿Y tú?', 'Me llamo Ola. ¿Y tú?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'fr', 'Je m''appelle Kuba. Et toi ?', 'Je m''appelle Ola. Et toi ?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'de', 'Ich heiße Kuba. Und du?', 'Ich heiße Ola. Und du?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'it', 'Mi chiamo Kuba. E tu?', 'Mi chiamo Ola. E tu?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'pt', 'Chamo-me Kuba. E tu?', 'Chamo-me Ola. E tu?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'be', 'Мяне завуць Куба. А цябе?', 'Мяне завуць Оля. А цябе?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'tr', 'Benim adım Kuba. Ya sen?', 'Benim adım Ola. Ya sen?'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'zh', '我叫库巴。你呢？', '我叫奥拉。你呢？'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'zh-Hant', '我叫庫巴。你呢？', '我叫奧拉。你呢？'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'ja', '名前はクバだよ。きみは？', '名前はオラだよ。きみは？'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'ar', 'اسمي كوبا. وأنت؟', 'اسمي أولا. وأنت؟'),
  ('5fec0dc7-de77-5747-9bc0-f948f863d80f', 'hi', 'मेरा नाम कूबा है। और तुम्हारा?', 'मेरा नाम ओला है। और तुम्हारा?'),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'pl', 'Tomek. Miło mi! Skąd jesteś?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'ru', 'Томек. Приятно познакомиться! Откуда ты?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'uk', 'Томек. Приємно познайомитися! Звідки ти?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'en', 'Tomek. Nice to meet you! Where are you from?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'es', 'Tomek. ¡Encantado! ¿De dónde eres?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'fr', 'Tomek. Enchanté ! Tu viens d''où ?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'de', 'Tomek. Freut mich! Woher kommst du?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'it', 'Tomek. Piacere! Di dove sei?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'pt', 'Tomek. Muito prazer! De onde és?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'be', 'Томек. Прыемна пазнаёміцца! Адкуль ты?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'tr', 'Tomek. Memnun oldum! Nerelisin?', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'zh', '托梅克。很高兴认识你！你是从哪儿来的？', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'zh-Hant', '托梅克。很高興認識你！你從哪裡來？', '托梅克。很高興認識妳！妳從哪裡來？'),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'ja', 'トメク。よろしく！どこから来たの？', null),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'ar', 'توميك. تشرفت! من أين أنتَ؟', 'توميك. تشرفت! من أين أنتِ؟'),
  ('bb47f3f7-f38b-5fd4-a20f-31905cac7a91', 'hi', 'तोमेक। तुमसे मिलकर ख़ुशी हुई! तुम कहाँ से हो?', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'pl', 'Mnie też miło! Jestem z lasu.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'ru', 'Мне тоже приятно! Я из леса.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'uk', 'Мені теж приємно! Я з лісу.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'en', 'Nice to meet you too! I''m from the forest.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'es', '¡Igualmente! Soy del bosque.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'fr', 'Enchanté aussi ! Je viens de la forêt.', 'Enchantée aussi ! Je viens de la forêt.'),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'de', 'Freut mich auch! Ich komme aus dem Wald.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'it', 'Piacere mio! Vengo dal bosco.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'pt', 'Igualmente! Sou da floresta.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'be', 'Мне таксама прыемна! Я з лесу.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'tr', 'Ben de memnun oldum! Ormanlıyım.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'zh', '我也很高兴认识你！我从森林里来。', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'zh-Hant', '我也很高興認識你！我來自森林。', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'ja', 'こっちこそよろしく！森から来たんだ。', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'ar', 'وأنا أيضًا تشرفت! أنا من الغابة.', null),
  ('ebc856d0-b403-51e8-b0a6-4fdb92b1464d', 'hi', 'मुझे भी ख़ुशी हुई! मैं जंगल से हूँ।', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'pl', 'Super! A gdzie teraz mieszkasz?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'ru', 'Супер! А где ты сейчас живёшь?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'uk', 'Супер! А де ти зараз живеш?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'en', 'Great! And where do you live now?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'es', '¡Genial! ¿Y dónde vives ahora?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'fr', 'Génial ! Et tu habites où maintenant ?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'de', 'Super! Und wo wohnst du jetzt?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'it', 'Fantastico! E dove abiti adesso?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'pt', 'Ótimo! E onde moras agora?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'be', 'Супер! А дзе ты цяпер жывеш?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'tr', 'Süper! Peki şimdi nerede yaşıyorsun?', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'zh', '太好了！那你现在住在哪儿？', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'zh-Hant', '太棒了！那你現在住在哪裡？', '太棒了！那妳現在住在哪裡？'),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'ja', 'いいね！で、今はどこに住んでるの？', null),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'ar', 'رائع! وأين تسكن الآن؟', 'رائع! وأين تسكنين الآن؟'),
  ('22c9b6fb-7a3d-5626-a62b-145acf4cf3f3', 'hi', 'बढ़िया! और अब तुम कहाँ रहते हो?', 'बढ़िया! और अब तुम कहाँ रहती हो?'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'pl', 'Mieszkam w Warszawie. Jestem tu nowy.', 'Mieszkam w Warszawie. Jestem tu nowa.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'ru', 'Я живу в Варшаве. Я тут новенький.', 'Я живу в Варшаве. Я тут новенькая.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'uk', 'Я живу у Варшаві. Я тут новенький.', 'Я живу у Варшаві. Я тут новенька.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'en', 'I live in Warsaw. I''m new here.', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'es', 'Vivo en Varsovia. Soy nuevo aquí.', 'Vivo en Varsovia. Soy nueva aquí.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'fr', 'J''habite à Varsovie. Je suis nouveau ici.', 'J''habite à Varsovie. Je suis nouvelle ici.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'de', 'Ich wohne in Warschau. Ich bin neu hier.', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'it', 'Abito a Varsavia. Sono nuovo qui.', 'Abito a Varsavia. Sono nuova qui.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'pt', 'Moro em Varsóvia. Sou novo aqui.', 'Moro em Varsóvia. Sou nova aqui.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'be', 'Я жыву ў Варшаве. Я тут новенькі.', 'Я жыву ў Варшаве. Я тут новенькая.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'tr', 'Varşova''da yaşıyorum. Burada yeniyim.', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'zh', '我住在华沙。我是新来的。', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'zh-Hant', '我住在華沙。我是新來的。', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'ja', 'ワルシャワに住んでるよ。ここに来たばかりなんだ。', null),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'ar', 'أسكن في وارسو. أنا جديد هنا.', 'أسكن في وارسو. أنا جديدة هنا.'),
  ('44ee1697-1018-58fa-b747-f7d25fd0edb3', 'hi', 'मैं वारसॉ में रहता हूँ। मैं यहाँ नया हूँ।', 'मैं वारसॉ में रहती हूँ। मैं यहाँ नई हूँ।'),
