  ('0d513434-abb5-53c2-9bcd-fea9221f314f', 'hi', 'कृपया', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'pl', 'Używaj najważniejszego polskiego słowa', null),
