  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'uk', 'Використовувати головне польське слово', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'en', 'Use the most useful Polish word', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'es', 'Usa la palabra más importante del polaco', null),
