  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'be', 'Карыстацца самым галоўным польскім словам', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'tr', 'En kullanışlı Lehçe kelimeyi kullan', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'zh', '用好最重要的波兰语单词', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'zh-Hant', '學會用最重要的波蘭語單字', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'ja', 'ポーランド語でいちばん便利な言葉を使おう', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'ar', 'استخدام أهم كلمة بولندية', null),
  ('87410b05-b43d-54f6-828f-c8ecdbf0e4a5', 'hi', 'पोलिश का सबसे काम का शब्द इस्तेमाल करें', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'ru', 'Proszę значит «пожалуйста», «вот, держите», «прошу» и «не за что» — смысл понятен из ситуации.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'uk', 'Proszę означає «будь ласка», «ось, тримайте», «прошу» і «нема за що» — зміст зрозумілий із ситуації.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'en', 'Proszę means “please”, “here you go”, and “you''re welcome” — the situation tells you which.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'es', 'Proszę significa «por favor», «aquí tiene» y «de nada»: la situación te dice cuál.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'fr', 'Proszę veut dire « s''il vous plaît », « tenez » et « je vous en prie » — c''est la situation qui le dit.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'de', 'Proszę heißt „bitte“, „hier, bitte“ und „gern geschehen“ – die Situation zeigt, was gemeint ist.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'it', 'Proszę vuol dire «per favore», «ecco a lei» e «prego»: lo capisci dalla situazione.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'pt', 'Proszę quer dizer «por favor», «aqui tem» e «de nada» — a situação diz-te qual.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'be', 'Proszę значыць «калі ласка», «вось, трымайце» і «няма за што» — што менавіта, зразумела з сітуацыі.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'tr', 'Proszę hem “lütfen”, hem “buyurun”, hem de “rica ederim” demektir; hangisi olduğunu durum gösterir.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'zh', 'Proszę 既是“请”，也是“给您”，还是“不客气”——具体是哪个意思，看场合。', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'zh-Hant', 'Proszę 可以是「請」、「給您」，也可以是「不客氣」——意思要看情況。', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'ja', 'Proszę には「お願いします」「どうぞ」「どういたしまして」の意味があります。どの意味かは場面でわかります。', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'ar', 'Proszę تعني «من فضلك» و«تفضّل» و«عفوًا» (ردًّا على الشكر)، والموقف يحدد المعنى المقصود.', null),
  ('26b24812-d6cd-52d7-adf3-80e1fa98bc7f', 'hi', 'Proszę का मतलब “कृपया”, “यह लीजिए” और “आपका स्वागत है” — तीनों होता है; कौन-सा, यह स्थिति से पता चलता है।', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'pl', 'Dzień dobry, słucham?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'ru', 'Здравствуйте, слушаю вас.', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'uk', 'Добрий день, слухаю вас.', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'en', 'Hello, what can I get you?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'es', 'Buenos días, ¿qué desea?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'fr', 'Bonjour, je vous écoute.', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'de', 'Guten Tag, ja bitte?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'it', 'Buongiorno, mi dica?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'pt', 'Bom dia, diga?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'be', 'Добры дзень, слухаю вас.', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'tr', 'Merhaba, buyurun?', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'zh', '您好，请问您要什么？', null),
  ('d048b6e1-35a6-5b97-83a5-5f9c2a98d32a', 'zh-Hant', '您好，請問您需要什麼？', null),
