  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'pl', 'Dzień dobry, słucham?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'ru', 'Здравствуйте, слушаю вас.', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'uk', 'Добрий день, слухаю вас.', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'en', 'Hello, what can I get you?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'es', 'Buenos días, ¿qué desea?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'fr', 'Bonjour, je vous écoute.', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'de', 'Guten Tag, ja bitte?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'it', 'Buongiorno, mi dica?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'pt', 'Bom dia, diga?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'be', 'Добры дзень, слухаю вас.', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'tr', 'Merhaba, buyurun?', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'zh', '您好，请问您要什么？', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'zh-Hant', '您好，請問您需要什麼？', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'ja', 'こんにちは、ご用件は？', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'ar', 'مرحبًا، كيف أخدمك؟', null),
  ('d96e5c28-0549-57d1-ae8f-5d079cf5edad', 'hi', 'नमस्ते, जी बताइए?', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'ru', '«Słucham?» говорят продавцы и в ответ на звонок. А ещё так переспрашивают: «Что, простите?»', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'uk', '«Słucham?» кажуть продавці й відповідаючи на дзвінок. А ще так перепитують: «Що, перепрошую?»', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'en', 'Shop staff say “Słucham?”, and so do people answering the phone. It also means “Sorry, what?”', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'es', 'Los dependientes dicen «Słucham?», y también quien contesta al teléfono. Además, significa «¿Perdón, cómo?».', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'fr', 'Les vendeurs disent « Słucham? », et on répond aussi comme ça au téléphone. Ça veut aussi dire « Pardon ? ».', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'de', '„Słucham?“ sagen Verkäufer, und so meldet man sich auch am Telefon. Es heißt außerdem „Wie bitte?“.', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'it', 'I commessi dicono «Słucham?», e così si risponde anche al telefono. Vuol dire anche «Scusi, come?»', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'pt', 'Os empregados das lojas dizem «Słucham?», e também quem atende o telefone. Também quer dizer «Desculpe, como?».', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'be', '«Słucham?» кажуць прадаўцы і тыя, хто адказвае на званок. А яшчэ так перапытваюць: «Прабачце, што?»', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'tr', '“Słucham?” diye satıcılar sorar, telefonu açanlar da böyle der. Ayrıca “Efendim?” anlamına da gelir.', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'zh', '店员会说“Słucham?”，接电话的人也这么说。它还可以表示“不好意思，您说什么？”', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'zh-Hant', '店員會說「Słucham?」，接電話時也會這麼說。它也可以表示「不好意思，您說什麼？」', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'ja', '「Słucham?」は店員さんも、電話に出る人も言います。聞き返すときの「はい？　何ですか？」という意味にもなります。', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'ar', 'يقول موظفو المتاجر «Słucham?»، وكذلك من يرد على الهاتف. وتعني أيضًا «عفوًا، ماذا قلت؟».', null),
  ('b2278176-7711-5e93-bbcd-db41a8fd1619', 'hi', 'दुकानदार “Słucham?” कहते हैं, और फ़ोन उठाने वाले भी। इसका मतलब “माफ़ कीजिए, क्या कहा?” भी होता है।', null),
