  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'pl', 'Przepraszam', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'ru', 'Извините', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'uk', 'Перепрошую', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'en', 'Excuse me', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'es', 'Perdón', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'fr', 'Excusez-moi', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'de', 'Entschuldigung', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'it', 'Mi scusi', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'pt', 'Desculpe', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'be', 'Прабачце', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'tr', 'Affedersiniz', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'zh', '不好意思', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'zh-Hant', '不好意思', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'ja', 'すみません', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'ar', 'عذرًا', null),
  ('4b0a069e-7907-5d70-a061-d968b23789f4', 'hi', 'माफ़ कीजिए', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'pl', 'Zagadaj do kogoś i przeproś', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'ru', 'Обратиться к кому-то и извиниться', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'uk', 'Звернутися до когось і вибачитися', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'en', 'Get someone''s attention and say sorry', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'es', 'Llama la atención de alguien y pide perdón', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'fr', 'Interpelle quelqu''un et excuse-toi', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'de', 'Sprich jemanden an und entschuldige dich', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'it', 'Attira l''attenzione di qualcuno e chiedi scusa', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'pt', 'Chama a atenção de alguém e pede desculpa', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'be', 'Звярнуцца да каго-небудзь і папрасіць прабачэння', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'tr', 'Birine seslen ve özür dile', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'zh', '和别人搭话，也学会道歉', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'zh-Hant', '跟別人搭話，也學會道歉', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'ja', '人に声をかけて、謝ろう', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'ar', 'لفت انتباه شخص ما والاعتذار', null),
  ('07a864f9-68de-5d47-b33f-ecff6ef9379d', 'hi', 'किसी का ध्यान खींचें और माफ़ी माँगें', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'ru', 'Przepraszam — это и «извините, можно вас?», и «простите, это моя вина».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'uk', 'Przepraszam — це і «перепрошую, можна вас?», і «вибачте, це моя провина».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'en', 'Przepraszam means both “excuse me” and “I''m sorry”.', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'es', 'Przepraszam significa a la vez «disculpe» y «lo siento».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'fr', 'Przepraszam veut dire à la fois « excusez-moi » et « pardon, je suis désolé ».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'de', 'Przepraszam heißt sowohl „Entschuldigung“ als auch „Es tut mir leid“.', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'it', 'Przepraszam vuol dire sia «mi scusi» sia «mi dispiace».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'pt', 'Przepraszam quer dizer tanto «com licença» como «desculpe».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'be', 'Przepraszam — гэта і «прабачце, можна вас?», і «выбачайце, гэта мая віна».', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'tr', 'Przepraszam hem “affedersiniz” hem de “özür dilerim” demektir.', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'zh', 'Przepraszam 既表示“打扰一下”，也表示“对不起”。', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'zh-Hant', 'Przepraszam 既可以表示「不好意思，打擾一下」，也可以表示「對不起」。', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'ja', 'Przepraszam は「すみません（ちょっといいですか）」と「ごめんなさい」の両方の意味で使います。', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'ar', 'Przepraszam تعني «عذرًا، لو سمحت» و«أعتذر» في آنٍ واحد.', null),
  ('31e67962-ca28-5c86-8bd5-e71f204f0b43', 'hi', 'Przepraszam के दो मतलब हैं: “सुनिए, ज़रा” और “माफ़ कीजिए, ग़लती हो गई”।', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'pl', 'Przepraszam, mogę przejść?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'ru', 'Извините, можно пройти?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'uk', 'Перепрошую, можна пройти?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'en', 'Excuse me, can I get through?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'es', 'Perdone, ¿puedo pasar?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'fr', 'Excusez-moi, je peux passer ?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'de', 'Entschuldigung, darf ich mal durch?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'it', 'Mi scusi, posso passare?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'pt', 'Com licença, posso passar?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'be', 'Прабачце, можна прайсці?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'tr', 'Affedersiniz, geçebilir miyim?', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'zh', '不好意思，能让我过去一下吗？', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'zh-Hant', '不好意思，可以借過一下嗎？', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'ja', 'すみません、通してもらえますか？', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'ar', 'عذرًا، هل يمكنني المرور؟', null),
  ('194471a4-5037-5f8e-a553-ae72c7c58db2', 'hi', 'माफ़ कीजिए, क्या मैं निकल सकती हूँ?', null),
  ('7ba4511d-4b07-5d2b-bae8-41e932e50ff0', 'pl', 'Tak, oczywiście. Przepraszam!', null),
  ('7ba4511d-4b07-5d2b-bae8-41e932e50ff0', 'ru', 'Да, конечно. Извините!', null),
  ('7ba4511d-4b07-5d2b-bae8-41e932e50ff0', 'uk', 'Так, звісно. Перепрошую!', null),
