  ('e7734412-f5d7-53f9-8048-779ad36ab03f', 'eceeb730-36b6-5af2-bf7b-87681ab1bdce', 10, '64dfd7ab-4089-5466-a375-227c533111da', 'Hello! Are you looking for something?', null),
  ('b36d7839-3b30-57d5-ad89-405f212d1840', 'eceeb730-36b6-5af2-bf7b-87681ab1bdce', 20, 'e9b47b93-6030-59a8-aa3a-a1ac53c2efce', 'Sorry, I speak a little English.', null),
  ('d461284e-e628-5fb7-9211-9c9a60d6414a', 'eceeb730-36b6-5af2-bf7b-87681ab1bdce', 30, '46afe064-4a5d-5c08-863f-665b9cdd9749', 'Sorry, I speak a little English.', null),
  ('3f7a111f-b074-5f3d-8e39-3fb0a4379b07', 'eceeb730-36b6-5af2-bf7b-87681ab1bdce', 40, '51a962d0-725e-5fbb-8892-f7a258146612', 'No, I don''t. I''m learning English.', null),
  ('fb2489c5-952a-5028-a11f-8bd3ff32677d', 'eceeb730-36b6-5af2-bf7b-87681ab1bdce', 50, '3f10fde8-8b36-5680-bdd5-e506560707e9', 'Thank you! I''m looking for a jacket.', null),
  ('4b742505-c33a-5c4e-bea0-68e3015466f5', 'db88f167-8572-52e1-b8bb-3fe11fb41744', 10, '78982b82-4875-55e8-8939-5ea4efa510ac', 'Hello! Are you our new neighbour?', null),
  ('c86a800b-f5a3-580c-8a80-5acde32f6428', 'db88f167-8572-52e1-b8bb-3fe11fb41744', 20, '312cba75-428c-5d83-9ad8-828f3c1b9b5a', 'I''m Thomas, but call me Tom.', null),
  ('e8029e36-0c18-5330-b365-c59371f4e8ed', 'db88f167-8572-52e1-b8bb-3fe11fb41744', 30, '306a9a2f-efd8-58c3-8b77-f59a9c034304', 'Sure! Nice to meet you, Tom.', null),
  ('7e0d3e2f-1c34-5fb1-917b-a204adef8cc1', 'db88f167-8572-52e1-b8bb-3fe11fb41744', 40, '7d6ffdd1-1636-505c-bf3f-7150e43a8097', 'You too! If you need anything, I live next door.', null),
  ('06dfccc6-23a2-5bdb-98b7-7c13c159d590', 'db88f167-8572-52e1-b8bb-3fe11fb41744', 50, 'b5f0018a-84cf-53ea-a4d5-7e14b322375c', 'You too! If you need anything, I live next door.', null),
  ('806f62ee-f6e8-5d7f-8621-747e0ef169f5', '99397893-5939-5f49-8650-f513d7c2183d', 10, 'f00fbd3b-1b28-5b72-b066-cbe227b15a6e', 'Hello! How can I help you?', null),
  ('ba84133d-195c-55d2-9e93-c946444ef298', '99397893-5939-5f49-8650-f513d7c2183d', 20, '906c465e-a9db-50dc-9b74-8c8fd50d0dac', 'Hello! Do you have a city map?', null),
