  ('83b5bddd-8149-52ae-8ff5-1c751f5522b6', '99397893-5939-5f49-8650-f513d7c2183d', 40, 'fc439229-60cd-5171-b43d-49a92e0c098f', 'No, I live here.', null),
  ('ef795fb3-ede8-57e7-ad60-20de4b39971f', '99397893-5939-5f49-8650-f513d7c2183d', 50, '8b7bd6d8-e7e5-53a6-a4f3-c1a77e2160e2', 'Then welcome to London!', null),
  ('75306e15-4fae-5aa4-a206-961cf22eddc6', '696c3a5d-c006-5b09-a95b-1ce22fd677f7', 10, 'c68e6b10-d12f-5bd5-8f37-bcbb4f059dc8', 'Please fill in this form.', null),
