  ('5e63f64a-b04e-57b5-9828-55112a68fbc4', '696c3a5d-c006-5b09-a95b-1ce22fd677f7', 30, '8769a66f-bab1-531f-ad9d-99ba43dd6a54', 'Could you say that again more slowly?', null),
  ('4e3633d7-a991-503c-8277-3ff0a7fe1b27', '696c3a5d-c006-5b09-a95b-1ce22fd677f7', 40, '4a9227d4-d459-5934-8420-5635dbf03601', 'Could you say that again more slowly?', null),
  ('6a59950b-c738-5763-ac97-66235e8b23c1', '696c3a5d-c006-5b09-a95b-1ce22fd677f7', 50, '07d0da24-9542-5528-969c-7bf9c251dabd', 'Oh, now I understand! Thank you.', null),
