  ('f2445ffb-27ac-5629-be31-6543f59e3c17', '945b966a-4d5f-5773-b15d-a33a3ecc8996', 30, 'a3f8e33b-760d-5de3-a048-b1887e591690', 'Yes, of course. Sorry!', null),
  ('ddcfe557-1a44-577c-b11a-dffd10a04df9', '945b966a-4d5f-5773-b15d-a33a3ecc8996', 40, '4e0846fc-07de-543c-b942-886a4bf279b5', 'Excuse me, where''s the toilet?', null),
