  ('850b91d8-f30a-5437-930c-c32f955e38c9', '1d5b737b-6dd8-56b6-8d7a-0514f2563f3d', 30, '4e4c16b1-f17f-5714-bf32-944423a5d2d8', 'Have a nice day, then!', null),
